const HIT_RATE = 0.8; // дефолт hit rate кэша (старые проекты без настройки hit_rate)

// ── Redis: память и hit rate ───────────────────────────────────
// '256mb' / '1gb' → МБ
function memMB(v,def){
  const m=String(v||'').trim().toLowerCase().match(/^([\d.]+)\s*(kb|mb|gb|tb)?$/);
  if(!m) return def;
  const n=+m[1], u=m[2]||'mb';
  return n*({kb:1/1024,mb:1,gb:1024,tb:1024*1024}[u]);
}
// Заполнение памяти: dataset / maxmemory (1 = ровно влезает). Дефолты 512mb / 1gb → 0.5 (старые проекты не задеты)
function redisFill(b){
  const s=b.settings||{};
  return memMB(s.dataset,512)/Math.max(1,memMB(s.maxmemory,1024));
}
// Эффективный hit rate кэш-блока.
// База — настройка hit_rate (%; дефолт 80). Если данные не влезают (fill>1) и политика вытесняющая,
// в памяти остаётся доля 1/fill рабочего набора. Доступы скошены (Zipf-подобно: горячие ключи часто),
// поэтому hit падает медленнее доли: hit = base · (1/fill)^α, где α — «качество» политики:
//   allkeys-LFU 0.35 (лучше всех держит горячее), allkeys-LRU 0.5, volatile-TTL 0.8 (вытесняет по TTL, не по популярности).
// noeviction hit rate не снижает — вместо этого запись падает с OOM (см. redisWriteErr).
function cacheHitRate(b){
  const s=(b&&b.settings)||{};
  let h=s.hit_rate!=null&&s.hit_rate!==''?(+s.hit_rate):HIT_RATE*100;
  if(!isFinite(h)) h=HIT_RATE*100;
  h=Math.max(0,Math.min(99,h))/100;
  if(b&&b.type==='redis'){
    const fill=redisFill(b), ev=String(s.eviction||'allkeys-LRU').toLowerCase();
    if(fill>1 && ev!=='noeviction'){
      const a=ev.includes('lfu')?0.35:ev.includes('ttl')?0.8:0.5;
      h*=Math.pow(1/fill,a);
    }
  }
  return h;
}
// noeviction + переполнение: доля записей, падающих с OOM = доля данных сверх maxmemory (1-1/fill).
// Записи — s.write_share% трафика кэша (дефолт 20%). Возвращает долю ВСЕХ запросов с ошибкой.
function redisWriteErr(b){
  if(!b||b.type!=='redis') return 0;
  const s=b.settings||{};
  if(String(s.eviction||'allkeys-LRU').toLowerCase()!=='noeviction') return 0;
  const fill=redisFill(b); if(fill<=1) return 0;
  const ws=Math.max(0,Math.min(100,s.write_share!=null?+s.write_share:20))/100;
  return ws*(1-1/fill);
}
// Hit rate для сервиса с Cache Aside: по подключённому кэш-блоку (несколько — лучший)
function svcHitRate(b, blocks, conns){
  let h=null;
  conns.forEach(c=>{ if(c.from!==b.id) return; const t=blocks.find(x=>x.id===c.to);
    if(t&&BASE[t.type]?.cat==='cache'){ const r=cacheHitRate(t); if(h==null||r>h) h=r; } });
  return h==null?HIT_RATE:h;
}

// ── PostgreSQL/MySQL: лимит соединений ─────────────────────────
// Каждый инстанс сервиса держит пул s.conn_pool (дефолт 10) соединений к БД.
// Спрос = Σ по входящим сервисам (replicas × pool). max_connections дефолт 100.
// Без пулера: при спросе > max_connections ёмкость падает пропорционально (max/спрос) — остальные ждут/отваливаются.
// С PgBouncer/Connection Pool: сотни клиентских соединений мультиплексируются в малый серверный пул — лимит снят, ёмкость НЕ растёт.
function dbConnDemand(b, env){
  const blocks=env&&env.blocks, conns=env&&env.conns;
  if(!blocks||!conns) return 0;
  let d=0;
  conns.forEach(c=>{ if(c.to!==b.id) return; const f=blocks.find(x=>x.id===c.from); if(!f) return;
    const cat=BASE[f.type]?.cat; if(cat!=='svc') return;
    const fs=f.settings||{}; d+=(fs.replicas||1)*(+fs.conn_pool||10); });
  return d;
}
function dbConnFactor(b, env){
  const s=b.settings||{};
  if(s.pgbouncer) return 1;
  const max=+s.max_connections||100, d=dbConnDemand(b,env);
  return d>max?max/d:1;
}
// ── PostgreSQL/MySQL: read/write split ────────────────────────
// Реплики чтения ускоряют ТОЛЬКО чтение: запись всегда идёт на праймари.
//   P = ёмкость праймари (база × лимит соединений × изоляция) — потолок по записи;
//   R = P·(1+0.7·replicas) — потолок по чтению (праймари + реплики).
//   Доля записи w: смесь держится, пока λ·w ≤ P и λ ≤ R → ёмкость = min(R, P/w).
// w — доля записи в трафике, дошедшем до БД. Если сервис задал write_share — записи идут мимо кэша,
// иначе берётся write_share самой БД (дефолт 20%). При w=20% и ≤5 репликах ёмкость как раньше.
const DB_WS_DEF=20;
function isRelDb(b){ return !!b&&(b.type==='postgresql'||b.type==='mysql'); }
function wsPct(s){ const v=s&&s.write_share; return (v!=null&&v!==''&&isFinite(+v))?Math.max(0,Math.min(100,+v)):null; }
function dbDefWs(b){ const p=wsPct(b&&b.settings); return (p!=null?p:DB_WS_DEF)/100; }
function dbWriteShare(b){ return (b&&b.rt&&b.rt.wShare!=null)?b.rt.wShare:dbDefWs(b); }
// Учесть поток в БД: w — явный объём записи (сервис с write_share) или null → доля write_share самой БД
function dbAddFlow(t, pass, w){ if(!isRelDb(t)) return; t.rt.lambdaW=(t.rt.lambdaW||0)+(w!=null?w:pass*dbDefWs(t)); }
// Ёмкости праймари (запись) и праймари+реплик (чтение)
function dbCaps(b, env){
  const base=BASE[b.type]; const s=b.settings||{};
  let cap=base.cap; cap*=dbConnFactor(b, env||_engEnv());
  let R=s.replicas?cap*(1+0.7*s.replicas):cap, P=cap;
  const iso=s.isolation==='SERIALIZABLE'?0.6:s.isolation==='REPEATABLE READ'?0.85:1;
  if(iso!==1){ R*=iso; P*=iso; }
  return {P,R};
}
// Лаг репликации: растёт, когда праймари загружен записью (реплики не успевают применять WAL/binlog)
function dbReplLag(rhoW, replicas){
  if(!replicas||!(rhoW>0)) return 0;
  if(rhoW>=1) return 5000;
  return Math.min(5000, Math.round(5/(1-rhoW)*(rhoW>0.6?Math.pow(rhoW/0.6,6):1)));
}
function _engEnv(){ return (typeof S!=='undefined'&&S&&S.blocks)?S:null; }

// ── Эффективная ёмкость с учётом настроек ──────────────────────
function effCap(b, env){
  const base=BASE[b.type]; if(!base) return 0;
  if(!isFinite(base.cap)) return Infinity;
  let cap=base.cap; const s=b.settings||{};
  switch(b.type){
    case 'service': case 'bff': case 'auth':
      cap *= (s.replicas||1); break;
    case 'queue':
      cap *= (s.workers||1); break;
    case 'elasticsearch':
      cap *= (s.shards||1); break;
    case 'api_gw': case 'websocket_gw':
      cap *= (s.instances||1); break;
    case 'lb':
      cap *= (s.instances||1); break;
    case 'postgresql': case 'mysql': {
      // PgBouncer снимает лимит соединений, но не умножает ёмкость; реплики — только чтение (см. dbCaps)
      const {P,R}=dbCaps(b, env); const w=dbWriteShare(b);
      cap=(s.replicas&&w>0)?Math.min(R,P/w):R;
      break; }
    case 'redis':
      if(s.cluster) cap*=Math.max(1,+s.cluster_shards||3); // ёмкость ∝ числу мастеров (слоты делятся между ними)
      if(s.persistence==='AOF') cap*=0.7;
      else if(s.persistence==='RDB') cap*=0.9;
      break;
    case 'kafka':
      cap = base.cap*((s.partitions||3)/3);
      if(s.delivery==='exactly-once') cap*=0.5;
      else if(s.delivery==='at-most-once') cap*=1.3;
      if(typeof kafkaCapMul==='function') cap*=kafkaCapMul(b); // acks / hot-key / хаос брокеров (1 для старых проектов)
      break;
    case 'cassandra':
      cap = base.cap*((s.nodes||3)/3);
      if(s.consistency==='ALL') cap*=0.5;
      else if(s.consistency==='ONE') cap*=1.5;
      break;
    case 'mongodb':
      if(s.sharding) cap*=4;
      if(s.replicas) cap*=(1+0.5*((s.replicas||1)-1));
      break;
    case 'clickhouse':
      cap *= (s.shards||1); break;
    case 'rabbitmq':
      if(s.mirrored) cap*=0.7; break;
    case 'nats':
      cap *= Math.max(1,+s.nodes||1); break; // NATS-кластер: ёмкость ∝ числу нод (по умолчанию 1 — как раньше)
  }
  if(b.down) return Math.max(1,(isFinite(cap)?cap:base.cap)*0.02);
  return cap;
}

// ── Эффективная задержка обработки с учётом настроек ───────────
function baseLat(b){
  const base=BASE[b.type]; let lat=base?base.lat:5; const s=b.settings||{};
  if((b.type==='postgresql'||b.type==='mysql')&&s.isolation==='SERIALIZABLE') lat*=1.4;
  if(b.type==='kafka'&&s.delivery==='exactly-once') lat*=1.5;
  if(b.type==='kafka'&&typeof kafkaLatMul==='function') lat*=kafkaLatMul(b);
  if(b.type==='redis'&&s.persistence==='AOF') lat*=1.3;
  if(b.type==='cassandra'&&s.consistency==='ALL') lat*=2;
  if(b.type==='nats') lat=0.5;
  if(b.chaosLat) lat*=b.chaosLat;
  return lat;
}

// ── Есть ли у сервиса Cache Aside И кэш в схеме ────────────────
function svcHasCache(b, blocks, conns){
  const pats=b.patterns||[];
  if(!pats.includes('cache_aside')) return false;
  return conns.some(c=>{
    if(c.from!==b.id) return false;
    const t=blocks.find(x=>x.id===c.to);
    return t && BASE[t.type]?.cat==='cache';
  });
}
function hasCB(b){return (b.patterns||[]).includes('circuit_breaker');}
function hasPat(b,p){return !!(b&&(b.patterns||[]).includes(p));}
// Rate Limit: лимит пропуска (Gateway — настройка rate_limit_rps, сервис — 70% своей ёмкости)
function rateLimitOf(b){
  if(!hasPat(b,'rate_limit')) return Infinity;
  const s=b.settings||{};
  if(b.type==='api_gw'||b.type==='websocket_gw') return +s.rate_limit_rps||1000;
  const c=effCap(b); return isFinite(c)?c*0.7:Infinity;
}

// ── ПОВЕДЕНИЕ AUTH: какая доля запросов реально идёт в хранилище ──
// session-based = stateful: каждый запрос читает сессию (100%).
// jwt-only = stateless: токен валиден по подписи, в БД только login/refresh (~10%).
// oauth2+jwt: выдача/интроспекция/refresh токенов (~20%).
// api_key = ключ проверяется в хранилище, но кэшируется (~30%).
// oidc_sso = внешний IdP, подписи по JWKS-кэшу; БД только онбординг/линковка (~5%).
function authType(b){return (b.auth&&b.auth.type)||(b.settings&&b.settings.authType)||'jwt_only';}
function authPassRate(b){
  const t=authType(b);
  if(t==='session_based')return 1.0;
  if(t==='api_key')return 0.3;
  if(t==='oauth2_jwt')return 0.2;
  if(t==='oidc_sso')return 0.05;
  return 0.1; // jwt_only
}

// ── Топологический порядок (Kahn). При цикле — как есть ────────
function topoOrder(blocks, conns){
  const indeg={}, adj={};
  blocks.forEach(b=>{indeg[b.id]=0;adj[b.id]=[];});
  conns.forEach(c=>{if(adj[c.from]){adj[c.from].push(c.to);indeg[c.to]=(indeg[c.to]||0)+1;}});
  const q=blocks.filter(b=>indeg[b.id]===0).map(b=>b.id);
  const order=[];
  while(q.length){
    const id=q.shift(); order.push(id);
    for(const nb of (adj[id]||[])){indeg[nb]--;if(indeg[nb]===0)q.push(nb);}
  }
  blocks.forEach(b=>{if(!order.includes(b.id))order.push(b.id);});
  return order;
}

// ══════════════════════════════════════════════════════════════
// ГЛАВНОЕ: расчёт потока нагрузки через граф
// ══════════════════════════════════════════════════════════════
function computeFlow(blocks, conns, load){
  const B=id=>blocks.find(b=>b.id===id);
  blocks.forEach(b=>{ b.rt={lambdaIn:0,cap:0,rho:0,dropRate:0,latMul:1,effLat:0,
    health:'ok',cascade:false,cbOpen:false,respTime:0,slowDueTo:null}; });

  const hasInc=new Set(conns.map(c=>c.to));
  const sources=blocks.filter(b=>!hasInc.has(b.id));
  // Нагрузка делится между источниками — total rps = load, не load×N
  const srcLoad=load/Math.max(1,sources.length);
  sources.forEach(s=>{ s.rt.lambdaIn += srcLoad; });

  const order=topoOrder(blocks,conns);

  for(const id of order){
    const b=B(id); if(!b) continue;
    let inL=b.rt.lambdaIn;
    const rl=rateLimitOf(b);
    if(inL>rl){ b.rt.rlDrop=1-rl/inL; inL=rl; }   // 🚦 лишнее отбивается 429 на входе
    const outs=conns.filter(c=>c.from===id);
    if(!outs.length) continue;
    const cat=BASE[b.type]?.cat;
    const isRouter=(cat==='gw'||cat==='net'||cat==='client'||cat==='actor');

    if(isRouter){
      const share=inL/outs.length;
      outs.forEach(c=>{const t=B(c.to);if(t){t.rt.lambdaIn+=share;dbAddFlow(t,share,null);}});
    } else {
      const cache=svcHasCache(b,blocks,conns);
      const hit=cache?svcHitRate(b,blocks,conns):0;
      const isAuth=(b.type==='auth');
      const aRate=isAuth?authPassRate(b):1;
      outs.forEach(c=>{
        const t=B(c.to); if(!t) return;
        const td=BASE[t.type]?.cat;
        let pass=inL;
        let w=null;
        const sw=(!isAuth&&isRelDb(t))?wsPct(b.settings):null;
        if(sw!=null){ w=inL*sw/100; pass=w+(inL-w)*(cache?(1-hit):1); } // запись идёт мимо кэша
        else if(cache && td==='db') pass=inL*(1-hit);
        else if(isAuth && (td==='db'||td==='cache')) pass=inL*aRate; // stateful/stateless
        t.rt.lambdaIn+=pass; dbAddFlow(t,pass,w);
      });
    }
  }

  finalizeFlow(blocks,conns);
  return blocks;
}

// ── РЕАЛИЗМ: нагрузка узла = сумма объёмов сценариев ──
// Учитывает cache hit rate (Cache Aside → DB получает только 20%) и authPassRate.
function computeFlowScenarios(blocks, conns, scenarios, _rlPass){
  const B=id=>blocks.find(x=>x.id===id);
  blocks.forEach(b=>{ b.rt={lambdaIn:0,cap:0,rho:0,dropRate:0,latMul:1,effLat:0,
    health:'ok',cascade:false,cbOpen:false,respTime:0,slowDueTo:null}; });
  (scenarios||[]).forEach(s=>{
    let v=s.volume||0; if(v<=0) return;
    const path=s.path||[];
    const seen=new Set();
    for(let i=0;i<path.length;i++){
      if(_rlPass&&i>0&&_rlPass[path[i-1]]!=null) v*=_rlPass[path[i-1]]; // 🚦 после Rate Limit дальше идёт меньше
      const id=path[i];
      if(seen.has(id))continue;
      seen.add(id);
      const b=B(id);if(!b)continue;
      let vol=v, w=null;
      if(i>0){
        const prev=B(path[i-1]);
        if(prev){
          const fc=BASE[prev.type]?.cat,tc=BASE[b.type]?.cat;
          const sw=(prev.type!=='auth'&&fc==='svc'&&isRelDb(b))?wsPct(prev.settings):null;
          const ch=svcHasCache(prev,blocks,conns);
          if(sw!=null){ w=v*sw/100; vol=w+(v-w)*(ch?(1-svcHitRate(prev,blocks,conns)):1); }
          else if(ch&&(tc==='db'||tc==='cache'))
            vol=v*(1-svcHitRate(prev,blocks,conns));
          else if(prev.type==='auth'&&(tc==='db'||tc==='cache'))
            vol=v*authPassRate(prev);
        }
      }
      b.rt.lambdaIn+=vol; dbAddFlow(b,vol,w);
    }
  });
  if(!_rlPass){
    // второй проход только если есть Rate Limit и он срабатывает (старые проекты не затронуты)
    const f={}; let any=false;
    blocks.forEach(b=>{ const rl=rateLimitOf(b); if(b.rt.lambdaIn>rl){ f[b.id]=rl/b.rt.lambdaIn; any=true; } });
    if(any){ computeFlowScenarios(blocks,conns,scenarios,f);
      blocks.forEach(b=>{ if(f[b.id]!=null) b.rt.rlDrop=1-f[b.id]; }); return blocks; }
  }
  finalizeFlow(blocks,conns);
  return blocks;
}

// ── Общая часть: по lambdaIn считаем загрузку, отказы, задержку, каскады ──
function finalizeFlow(blocks, conns){
  const B=id=>blocks.find(b=>b.id===id);
  const env={blocks,conns};
  blocks.forEach(b=>{
    if(isRelDb(b)) b.rt.wShare=b.rt.lambdaIn>0&&b.rt.lambdaW!=null?Math.min(1,b.rt.lambdaW/b.rt.lambdaIn):dbDefWs(b);
    const cap=effCap(b, env);
    b.rt.lambdaIn=Math.round(b.rt.lambdaIn);
    b.rt.cap=cap;
    b.rt.rho=isFinite(cap)?(cap>0?b.rt.lambdaIn/cap:99):0;
    const r=b.rt.rho;
    // r≤0.8: нет потерь; r∈(0.8,1): 0→8% линейно; r≥1: max(8%,(λ-cap)/λ) — непрерывно
    b.rt.dropRate=r<=0.8?0:r>=1?Math.min(0.95,Math.max(0.08,1-1/r)):(r-0.8)*0.4;
    b.rt.latMul=r<1?Math.min(1/(1-r),20):20;
    b.rt.effLat=baseLat(b)*b.rt.latMul;
    b.rt.health=r>=0.9?'error':r>=0.6?'warn':'ok';
    if(b.type==='postgresql'||b.type==='mysql'){ const s=b.settings||{}; const f=dbConnFactor(b,env); if(f<1) b.rt.connLimited={demand:dbConnDemand(b,env),max:+s.max_connections||100};
      // read/write split: где потолок — в записи (праймари) или в чтении (реплики)
      const {P,R}=dbCaps(b,env), w=b.rt.wShare, lw=b.rt.lambdaIn*w;
      b.rt.capW=P; b.rt.capR=R; b.rt.lambdaWr=Math.round(lw); b.rt.rhoW=P>0?lw/P:0;
      b.rt.writeBound=!!(s.replicas&&w>0&&P/w<R);
      b.rt.replLag=dbReplLag(b.rt.rhoW, +s.replicas||0); }
    if(b.type==='redis'){
      b.rt.hitRate=cacheHitRate(b);
      const oom=redisWriteErr(b);
      if(oom>0 && b.rt.lambdaIn>0){ b.rt.oomErr=oom; b.rt.dropRate=Math.min(0.95,Math.max(b.rt.dropRate,oom)); if(b.rt.health==='ok') b.rt.health=oom>=0.1?'error':'warn'; }
    }
  });
  const memo={};
  function respTime(id, seen){
    if(memo[id]!=null) return memo[id];
    if(seen.has(id)) return 0;
    seen.add(id);
    const b=B(id); if(!b){return 0;}
    let down=0, slowDep=null;
    const outs=conns.filter(c=>c.from===id);
    for(const c of outs){
      const t=B(c.to); if(!t) continue;
      const tcat=BASE[t.type]?.cat;
      if(tcat==='broker'||tcat==='queue') continue;
      if(hasCB(b) && t.rt.health==='error'){ b.rt.cbOpen=true; continue; }
      const rt=respTime(t.id, new Set(seen));
      if(rt>down){down=rt;slowDep=t.id;}
    }
    b.rt.slowDep=slowDep;
    memo[id]=b.rt.effLat+down;
    return memo[id];
  }
  blocks.forEach(b=>{ b.rt.respTime=respTime(b.id, new Set()); });
  blocks.forEach(b=>{
    const cat=BASE[b.type]?.cat;
    if((hasPat(b,'bulkhead')||hasPat(b,'fallback')) && b.rt.slowDep){ b.rt.isolated=true; return; } // 🛡/🪂 медленная зависимость не тянет вызывающего
    if((cat==='svc'||cat==='gw') && b.rt.health!=='error' && !b.rt.cbOpen){
      const wait=b.rt.respTime-b.rt.effLat;
      if(wait>Math.max(b.rt.effLat*2,15)){
        b.rt.cascade=true;
        b.rt.slowDueTo=b.rt.slowDep;
        if(b.rt.health==='ok') b.rt.health='warn';
      }
    }
  });
  if(typeof kafkaAnnotateFlow==='function') kafkaAnnotateFlow(blocks,conns);
  return blocks;
}

// ══════════════════════════════════════════════════════════════
// МОДЕЛЬ БРОКЕРА — Kafka, RabbitMQ, NATS, Queue
// Сервис может быть одновременно продюсером (produces[]) и консьюмером (consumes[])
// ══════════════════════════════════════════════════════════════
const BROKER_STATE = {}; // keyed by blockId

function initBrokerState(b){
  if(BROKER_STATE[b.id]) return BROKER_STATE[b.id];
  const state = {
    type: b.type,
    topics: {},        // topicName -> partitions[]
    queues: {},        // queueName -> messages[]
    consumerGroups: {}, // groupId -> {topics: {topicName -> {partitionIdx -> offset}}}
    dlq: [],           // dead letter queue
    failedCount: 0,
    lostCount: 0,      // NATS core (без JetStream): сообщения без подписчика теряются
    totalProduced: 0,
    totalConsumed: 0,
  };
  // Создаём дефолтный топик/очередь
  BROKER_STATE[b.id] = state;
  if(b.type==='kafka'){
    kafkaInit(b,state); // модель v2: kafka-engine.js
  } else {
    state.queues['default'] = [];
  }
  BROKER_STATE[b.id] = state;
  return state;
}
// Оффсеты группы по топику (создать нули если не было)
function grpTopicOffsets(state, groupId, topic, partsCount){
  if(!state.consumerGroups[groupId]) state.consumerGroups[groupId]={topics:{}};
  const grp=state.consumerGroups[groupId];
  if(!grp.topics) grp.topics={};
  if(!grp.topics[topic]) grp.topics[topic]=Object.fromEntries(Array.from({length:partsCount},(_,i)=>[i,0]));
  return grp.topics[topic];
}

// Продюсер пишет сообщение в брокер
function brokerProduce(brokerId, message){
  const b = (typeof gb==='function')?gb(brokerId):null;
  if(!b) return false;
  const state = initBrokerState(b);
  const s = b.settings||{};
  message = message||{};
  const mkMsg = body => ({
    id: 'msg_'+Date.now()+'_'+Math.random().toString(36).slice(2),
    body: body||{},
    timestamp: Date.now(),
    status: 'pending',
    retries: 0,
  });

  if(b.type==='kafka') return kafkaProduce(b,state,message);

  if(b.type==='nats' && !s.jetstream){
    // NATS core = at-most-once, ничего не хранит:
    // есть подписчики → мгновенный fan-out каждому; нет — сообщение ПОТЕРЯНО
    const subs = (typeof S!=='undefined')?S.conns.filter(c=>c.from===b.id):[];
    state.totalProduced++;
    if(!subs.length){ state.lostCount++; return {ack:true, lost:true}; }
    state.totalConsumed += subs.length; // копия каждому подписчику, очередь не растёт
    return {ack:true, fanout:subs.length};
  }

  if(b.type==='rabbitmq'){
    // Exchange-модель: direct → одна очередь; fanout → копия в очередь КАЖДОГО консьюмера;
    // topic → очередь по routing key (упрощённо как direct с паттерном)
    const ex = s.exchange||'direct';
    state.totalProduced++;
    if(ex==='fanout'){
      const consumers = (typeof S!=='undefined')?S.conns.filter(c=>c.from===b.id).map(c=>gb(c.to)).filter(Boolean):[];
      const targets = consumers.length?consumers:[null];
      targets.forEach(t=>{
        const qn = t?('q_'+(t.customLabel||t.id)):'default';
        if(!state.queues[qn]) state.queues[qn]=[];
        state.queues[qn].push(mkMsg(message.value||message.body));
      });
      return {ack:true, fanout:targets.length};
    }
    const q = message.queue||(ex==='topic'?(message.routingKey||'default'):'default');
    if(!state.queues[q]) state.queues[q]=[];
    state.queues[q].push(mkMsg(message.value||message.body));
    return {ack:true};
  }

  // Queue / NATS JetStream — простая очередь
  const q = message.queue||'default';
  if(!state.queues[q]) state.queues[q]=[];
  state.queues[q].push(mkMsg(message.value||message.body));
  state.totalProduced++;
  return {ack:true};
}

// Консьюмер читает сообщение из брокера
function brokerConsume(brokerId, opts){
  opts = opts||{};
  const b = (typeof gb==='function')?gb(brokerId):null;
  if(!b) return null;
  const state = BROKER_STATE[brokerId];
  if(!state) return null;
  const groupId = opts.groupId||'default-group';
  const delivery = (b.settings||{}).delivery||'at-least-once';

  if(b.type==='kafka'){
    const topic = opts.topic||kTopicName(b); // было 'default' при записи в 'events' — баг
    const parts = state.topics[topic];
    if(!parts) return null;
    const offs = grpTopicOffsets(state, groupId, topic, parts.length); // оффсеты СВОЕГО топика
    // ищем партицию с необработанными сообщениями
    for(let pi=0;pi<parts.length;pi++){
      const offset = Math.max(offs[pi]||0, parts[pi].base||0);
      const msg = kReadAt(parts[pi], offset);
      if(msg){
        // at-most-once: сразу коммитим
        if(delivery==='at-most-once') offs[pi] = msg.offset+1;
        return {msg, partition:pi, offset:msg.offset, groupId, topic,
          commit: ()=>{ offs[pi]=msg.offset+1; state.totalConsumed++; },
          nack: ()=>{
            state.dlq.push({...msg, failReason:'consumer_error', dlqAt:Date.now()});
            state.failedCount++;
            offs[pi]=msg.offset+1; // пропускаем
          }
        };
      }
    }
    return null;
  } else {
    const q = opts.queue||'default';
    const queue = state.queues[q];
    if(!queue||!queue.length) return null;
    const msg = queue[0];
    const ack = (b.settings||{}).ack||'manual';
    if(ack==='auto') { queue.shift(); state.totalConsumed++; }
    return {msg, commit:()=>{queue.shift();state.totalConsumed++;},
      nack:()=>{state.dlq.push({...msg,failReason:'nack',dlqAt:Date.now()});state.failedCount++;queue.shift();}};
  }
}

// Replay: сброс оффсетов для группы (по всем её топикам)
function brokerReplay(brokerId, groupId){
  const state = BROKER_STATE[brokerId];
  if(!state) return;
  groupId = groupId||'default-group';
  const grp = state.consumerGroups[groupId];
  if(grp&&grp.topics){
    Object.values(grp.topics).forEach(offs=>{
      Object.keys(offs).forEach(k=>{ offs[k]=0; }); // < base → читаем с начала лога (logStartOffset)
    });
  }
}

// Лаг консьюмера по топику (разница между последним сообщением и оффсетом группы)
function brokerConsumerLag(brokerId, groupId, topic){
  const state = BROKER_STATE[brokerId];
  if(!state) return 0;
  const b = (typeof gb==='function')?gb(brokerId):null;
  groupId = groupId||'default-group';
  topic = topic||(b&&b.type==='kafka'?kTopicName(b):'default');
  const parts = state.topics[topic];
  if(!parts) return 0;
  const offs = state.consumerGroups[groupId]?.topics?.[topic];
  const hw = p => p.hw!=null?p.hw:p.messages.length;
  if(!offs) return parts.reduce((a,p)=>a+hw(p)-(p.base||0),0);
  return parts.reduce((a,p,i)=>a+Math.max(0,hw(p)-Math.max(offs[i]||0,p.base||0)),0);
}

// Для NATS: pub/sub fan-out ко всем подписчикам (возвращает список потребителей)
function natsFanOut(brokerId, blocks, conns, message){
  const consumers = conns.filter(c=>c.from===brokerId).map(c=>blocks.find(b=>b.id===c.to)).filter(Boolean);
  return consumers.map(c=>({consumerId:c.id, msg:message, delivered:true}));
}

function hashStr(s){
  let h=0; for(let i=0;i<s.length;i++){h=(Math.imul(31,h)+s.charCodeAt(i))|0;} return h;
}

// Получить состояние брокера для инспектора
function getBrokerInspectorData(brokerId){
  const b = (typeof gb==='function')?gb(brokerId):null;
  if(!b) return null;
  const state = BROKER_STATE[brokerId];
  if(!state) return {type:b.type, empty:true, totalProduced:0, totalConsumed:0, dlq:[], consumerGroups:{}};
  const result = {
    type: b.type,
    totalProduced: state.totalProduced,
    totalConsumed: state.totalConsumed,
    dlqCount: state.dlq.length,
    failedCount: state.failedCount,
    lostCount: state.lostCount||0,
    dlq: state.dlq.slice(-10), // последние 10
    consumerGroups: {},
    topics: {},
    queues: {},
  };
  if(b.type==='kafka'){
    Object.assign(result,{kafka:true, cfg:state.cfg, brokers:state.brokers, tick:state.tick, rebalances:state.rebalances, log:(state.log||[]).slice(-12),
      expiredCount:state.expiredCount, compactedCount:state.compactedCount, rejectedCount:state.rejectedCount,
      retriedCount:state.retriedCount, dupCount:state.dupCount});
    Object.entries(state.topics).forEach(([topic,parts])=>{
      result.topics[topic] = { kind:state.topicMeta?.[topic]?.kind||'main',
        partitions: parts.map((p,i)=>({
          index:i,
          messages:p.messages.length,
          highWatermark:p.hw,
          logStart:p.base,
          produced:p.produced,
          leader:p.leader, replicas:p.replicas, isr:p.isr, offline:p.offline,
        })),
      };
    });
    Object.entries(state.consumerGroups).forEach(([gid,grp])=>{
      // лаг группы = сумма лагов по ЕЁ топикам (каждый топик против своих оффсетов)
      let lag=0; const perTopic={}, perPart={};
      Object.entries(grp.topics||{}).forEach(([topic,offs])=>{
        const parts=state.topics[topic]; if(!parts)return;
        let tLag=0; perPart[topic]={};
        parts.forEach((p,i)=>{ const l=kLagPart(p,offs[i]); perPart[topic][i]=l; tLag+=l; });
        perTopic[topic]=tLag; lag+=tLag;
      });
      result.consumerGroups[gid] = {lag, topics:perTopic, partLag:perPart, members:grp.members||[], assignment:grp.assignment||{},
        blockId:grp.blockId, label:grp.label, generation:grp.generation||0, consumed:grp.consumed||0, failed:grp.failed||0,
        rebalancing:(grp.pause||0)>0||Object.values(grp.paused||{}).some(v=>v>0)};
    });
  } else {
    Object.entries(state.queues).forEach(([q,msgs])=>{
      result.queues[q] = {pending:msgs.length};
    });
  }
  return result;
}

// Очистить состояние брокеров
function resetBrokerStates(){
  Object.keys(BROKER_STATE).forEach(k=>delete BROKER_STATE[k]);
}

// ── Периодическое потребление сообщений (вызывается из simLoop каждые N кадров) ──
// Полностью отвязано от физики шариков: консьюмеры опрашивают брокер асинхронно.
function tickBrokerConsumers(){
  if(typeof S==='undefined') return;
  const conns = S.conns||[];
  Object.keys(BROKER_STATE).forEach(function(bId){
    const b = (typeof gb==='function')?gb(bId):null; if(!b) return;
    const state = BROKER_STATE[bId]; if(!state) return;
    const delivery = (b.settings||{}).delivery || 'at-least-once';

    if(b.type==='kafka'){
      kafkaTick(b,state); // группы, назначение партиций, ретраи/DLQ — kafka-engine.js
    } else {
      // RabbitMQ / Queue / NATS JetStream — дрейним очереди
      Object.values(state.queues||{}).forEach(function(queue){
        var batch = Math.min(3, queue.length);
        for(var i=0;i<batch;i++){
          if(!queue.length) break;
          var fail = Math.random()<0.015;
          if(fail){
            state.dlq.push({...queue[0], failReason:'nack', dlqAt:Date.now()});
            state.failedCount++;
          } else { state.totalConsumed++; }
          queue.shift();
        }
      });
    }
  });
}


;
// ===== kafka-engine.js =====
// KAFKA-ENGINE — модель Kafka v2 (без DOM): брокеры/реплики/ISR, партиционирование по ключу,
// consumer groups (каждый сервис-подписчик = своя группа, его реплики = члены группы),
// назначение партиций (range / roundrobin / cooperative-sticky), ребаланс, retention/compaction,
// retry-топик + DLQ, хаос (падение брокера). Вызывается из engine.js (initBrokerState/brokerProduce/...).
// Совместимость: старые проекты без новых настроек дают тот же effCap/computeFlow.

const KAFKA_CHAOS = {};            // blockId -> {down:{brokerIdx:true}} — переживает resetBrokerStates
const KAFKA_HOT_SHARE = 0.55;      // доля трафика «горячего» ключа при key_strategy=hot-key

function _kclamp(v,a,b){return Math.max(a,Math.min(b,v));}

// Имя основного топика: настройка → подпись блока (если похожа на имя топика) → 'events'
function kTopicName(b){
  const s=b.settings||{};
  if(s.topic_name) return String(s.topic_name);
  const lbl=(b.customLabel||'').trim();
  if(lbl && /^[A-Za-z0-9._-]+$/.test(lbl)) return lbl;
  return 'events';
}

// Нормализованная конфигурация (дефолты = поведение Kafka 3.x)
function kafkaCfg(b){
  const s=b.settings||{};
  const rf=_kclamp(+s.replication||3,1,5);
  const brokers=Math.max(_kclamp(+s.brokers||3,1,12), rf);
  return {
    topic: kTopicName(b),
    partitions: _kclamp(Math.round(+s.partitions||3),1,64),
    rf, brokers,
    minIsr: _kclamp(+s.min_insync||Math.min(2,rf),1,rf),
    acks: s.acks||'all',
    delivery: s.delivery||'at-least-once',
    assignor: s.assignor||'range',
    keyStrategy: s.key_strategy||'by-entity',
    cleanup: s.cleanup||'delete',
    retention: _kclamp(+s.retention_msgs||300,20,100000),
    retryDlq: s.retry_dlq!==false && !(s.on_error||'').startsWith('redeliver'),
    maxRetries: _kclamp(s.max_retries==null?3:+s.max_retries,0,10),
    pollRate: _kclamp(+s.poll_rate||6,1,100),   // сообщений за тик на одного консьюмера
  };
}

// ── Влияние на аналитическую модель (только явно заданные новые настройки + хаос) ──
function kafkaHotShare(P){ return KAFKA_HOT_SHARE + (1-KAFKA_HOT_SHARE)/Math.max(1,P); }
function kafkaCapMul(b){
  const s=b.settings||{}; let m=1;
  // базовая модель = acks=all (как было); 1/0 — быстрее, но менее надёжно
  if(s.acks==='1') m*=1.1; else if(s.acks==='0') m*=1.2;
  if(s.key_strategy==='hot-key'){
    const P=+s.partitions||3, h=kafkaHotShare(P);
    m*=Math.min(1, 1/(P*h));          // упираемся в одну (лидер-)партицию
  }
  const h=kafkaHealth(b);
  if(h){
    if(h.alive<h.brokers) m*=Math.max(0.05,h.alive/h.brokers);
    if(h.writeBlocked||h.offlineParts>=h.partitions) m*=0.02;
    else if(h.offlineParts) m*=Math.max(0.05,1-h.offlineParts/h.partitions);
  }
  return m;
}
function kafkaLatMul(b){
  const s=b.settings||{};
  if(s.acks==='1') return 0.8; if(s.acks==='0') return 0.5; return 1;
}

// Статическое здоровье кластера по хаосу (без запущенной симуляции тоже работает)
function kafkaHealth(b){
  const ch=KAFKA_CHAOS[b.id]; if(!ch||!Object.keys(ch.down||{}).length) return null;
  const c=kafkaCfg(b); let offline=0, underMin=0;
  for(let p=0;p<c.partitions;p++){
    const reps=kReplicas(p,c); const alive=reps.filter(r=>!ch.down[r]).length;
    if(!alive) offline++; else if(alive<c.minIsr) underMin++;
  }
  const alive=c.brokers-Object.keys(ch.down).filter(k=>ch.down[k]&&+k<c.brokers).length;
  return {brokers:c.brokers, alive, partitions:c.partitions, offlineParts:offline, underMinIsr:underMin,
    writeBlocked: c.acks==='all' && underMin+offline>=c.partitions};
}

// События: для анимации (sim дренирует) + короткий журнал для инспектора
const K_LOG_TYPES={rebalance:1,leader:1,broker_down:1,broker_up:1,dlq:1,expired:1,rejected:1,lost:1,redeliver:1,compacted:0,retry:1};
function kEv(state,e){
  if(!state.events) state.events=[];
  e.tick=state.tick||0; state.events.push(e);
  if(state.events.length>3000) state.events.splice(0,state.events.length-3000);
  if(K_LOG_TYPES[e.type]){ if(!state.log) state.log=[]; const last=state.log[state.log.length-1];
    if(last&&last.type===e.type&&last.gid===(e.gid||null)&&e.type!=='rebalance'&&e.type!=='leader'){ last.n++; last.tick=e.tick; }
    else { state.log.push({type:e.type,gid:e.gid||null,n:1,tick:e.tick,broker:e.broker,partition:e.partition,leader:e.leader,members:e.members,eager:e.eager,error:e.error}); if(state.log.length>40) state.log.shift(); } }
}

function kReplicas(p,c){ const r=[]; for(let i=0;i<c.rf;i++) r.push((p+i)%c.brokers); return r; }

// ── Состояние ──
function kafkaInit(b,state){
  const c=kafkaCfg(b);
  state.kafka=true; state.cfg=c; state.tick=0; state.rr=0;
  state.topicMeta={}; state.events=[]; state.log=[]; state.rebalances=0;
  state.expiredCount=0; state.compactedCount=0; state.rejectedCount=0; state.retriedCount=0; state.dupCount=0;
  state.brokers=Array.from({length:c.brokers},(_,i)=>({id:i, up:!(KAFKA_CHAOS[b.id]?.down?.[i])}));
  kEnsureTopic(state,c.topic,'main');
  kafkaSyncGroups(b,state);
  return state;
}

function kEnsureTopic(state,name,kind){
  if(state.topics[name]) return state.topics[name];
  const c=state.cfg;
  const P=kind==='dlq'?1:c.partitions;
  state.topics[name]=Array.from({length:P},(_,i)=>{
    const replicas=kReplicas(i,c);
    const part={index:i, messages:[], base:0, hw:0, replicas, isr:replicas.slice(), leader:replicas[0], offline:false, produced:0, catchUp:{}};
    kRefreshPartition(state,part);
    return part;
  });
  state.topicMeta[name]={kind};
  return state.topics[name];
}
function kUp(state,i){ return !!(state.brokers[i]&&state.brokers[i].up); }
function kRefreshPartition(state,part){
  part.isr=part.isr.filter(r=>kUp(state,r));
  if(part.leader==null||!kUp(state,part.leader)){
    const prev=part.leader;
    part.leader=part.isr.length?part.isr[0]:null;     // чистые выборы лидера только из ISR
    if(prev!==part.leader && part.leader!=null) kEv(state,{type:'leader',partition:part.index,leader:part.leader});
  }
  part.offline=part.leader==null;
}

// Хаос: уронить / поднять брокер
function kafkaSetBrokerUp(blockId, idx, up){
  if(!KAFKA_CHAOS[blockId]) KAFKA_CHAOS[blockId]={down:{}};
  if(up) delete KAFKA_CHAOS[blockId].down[idx]; else KAFKA_CHAOS[blockId].down[idx]=true;
  const state=BROKER_STATE[blockId];
  if(state&&state.kafka&&state.brokers[idx]){
    state.brokers[idx].up=!!up;
    Object.values(state.topics).forEach(parts=>parts.forEach(p=>{
      if(up){ if(p.replicas.includes(idx)&&!p.isr.includes(idx)) p.catchUp[idx]=3; } // догоняет 3 тика → в ISR
      kRefreshPartition(state,p);
    }));
    kEv(state,{type:up?'broker_up':'broker_down',broker:idx});
  }
}
function kafkaResetChaos(blockId){ delete KAFKA_CHAOS[blockId]; const st=BROKER_STATE[blockId];
  if(st&&st.kafka){ st.brokers.forEach(x=>x.up=true); Object.values(st.topics).forEach(ps=>ps.forEach(p=>{p.isr=p.replicas.slice();kRefreshPartition(st,p);})); } }

// ── Ключи и партиционер ──
function kGenKey(c){
  if(c.keyStrategy==='null') return null;
  if(c.keyStrategy==='hot-key' && Math.random()<KAFKA_HOT_SHARE) return 'celebrity-42';
  return 'id-'+Math.floor(Math.random()*5000);
}
function kPartitionFor(state,parts,key){
  if(key==null){ state.rr=(state.rr+1)%parts.length; return state.rr; } // sticky/round-robin
  return Math.abs(hashStr(String(key)))%parts.length;               // murmur2 в реальности; тут простой hash
}

function kAppend(state,part,msg){
  msg.offset=part.hw++; part.messages.push(msg); part.produced++;
  kRetention(state,part,msg.topic);
}

// Retention (delete) / log compaction (compact)
function kRetention(state,part,topic){
  const c=state.cfg; if(part.messages.length<=c.retention) return;
  const minOff=kMinCommitted(state,topic,part.index);
  if(c.cleanup==='compact'){
    const lastByKey={}; part.messages.forEach((m,i)=>{ if(m.key!=null) lastByKey[m.key]=i; });
    const head=part.messages.length-Math.floor(c.retention/2);   // «активный сегмент» не трогаем
    const keep=[];
    part.messages.forEach((m,i)=>{
      if(i>=head || m.key==null || lastByKey[m.key]===i) keep.push(m);
      else { state.compactedCount++; if(m.offset>=minOff) kEv(state,{type:'compacted',msg:m}); }
    });
    part.messages=keep;
    while(part.messages.length>c.retention){ const m=part.messages.shift(); kExpire(state,m,minOff); }
  } else {
    while(part.messages.length>c.retention){ const m=part.messages.shift(); kExpire(state,m,minOff); }
  }
  part.base=part.messages.length?part.messages[0].offset:part.hw;
}
function kExpire(state,m,minOff){
  if(m.offset>=minOff){ state.expiredCount++; kEv(state,{type:'expired',msg:m}); }
}
function kMinCommitted(state,topic,pi){
  let mn=Infinity;
  Object.values(state.consumerGroups).forEach(g=>{ const o=g.topics?.[topic]; if(o&&g.members&&g.members.length) mn=Math.min(mn,o[pi]||0); });
  return mn===Infinity?0:mn;
}

// Продюсер
function kafkaProduce(b,state,message){
  const c=state.cfg; message=message||{};
  const topic=message.topic||c.topic;
  const kind=topic.endsWith('.dlq')?'dlq':topic.endsWith('.retry')?'retry':'main';
  const parts=kEnsureTopic(state,topic,kind);
  if(kind==='retry'&&message.forGroup&&!state.topicMeta[topic].group) state.topicMeta[topic].group=message.forGroup;
  const key=('key' in message)?message.key:kGenKey(c);
  const pi=message.partition!=null?message.partition%parts.length:kPartitionFor(state,parts,key);
  const part=parts[pi];
  kRefreshPartition(state,part);
  state.totalProduced++;
  if(part.offline){
    state.rejectedCount++; kEv(state,{type:'rejected',error:'LEADER_NOT_AVAILABLE',partition:pi,reqId:message.reqId});
    if(c.acks==='0'){ state.lostCount++; return {ack:true,lost:true,partition:pi,error:'OFFLINE_PARTITION'}; }
    return {ack:false,partition:pi,error:'LEADER_NOT_AVAILABLE'};
  }
  if(c.acks==='all' && part.isr.length<c.minIsr){
    state.rejectedCount++; kEv(state,{type:'rejected',error:'NOT_ENOUGH_REPLICAS',partition:pi,reqId:message.reqId});
    return {ack:false,partition:pi,error:'NOT_ENOUGH_REPLICAS'};
  }
  const msg={key, value:message.value||message.body||{}, timestamp:Date.now(), status:'pending', topic, partition:pi,
    attempt:message.attempt||0, readyTick:message.readyTick||0, reqId:message.reqId||(message.value&&message.value.req)||null, origTopic:message.origTopic||null};
  kAppend(state,part,msg);
  return {ack:true, partition:pi, offset:msg.offset, key, leader:part.leader, isr:part.isr.length};
}

// ── Consumer groups ──
function kRetryTopic(base,gid){ return base+'.'+String(gid).replace(/-group$/,'')+'.retry'; }
function kGroupId(cb){
  const s=cb.settings||{};
  if(s.group_id) return String(s.group_id);
  const base=(cb.customLabel||cb.type||'svc').toString().toLowerCase().replace(/[^a-zа-яё0-9]+/gi,'-').replace(/^-|-$/g,'');
  return (base||'svc')+'-group';
}
function kInstances(cb){ const s=cb.settings||{}; return _kclamp(+(s.replicas||s.workers||s.instances||1),1,32); }

function kafkaSyncGroups(b,state){
  if(typeof S==='undefined') return;
  const c=state.cfg;
  const consumers=(S.conns||[]).filter(x=>x.from===b.id).map(x=>gb(x.to)).filter(Boolean);
  const seen={};
  consumers.forEach(cb=>{
    const gid=kGroupId(cb); seen[gid]=true;
    let g=state.consumerGroups[gid];
    if(!g) g=state.consumerGroups[gid]={gid, blockId:cb.id, topics:{}, members:[], assignment:{}, generation:0, pause:0, paused:{}, consumed:0, failed:0, sig:''};
    g.blockId=cb.id; g.label=cb.customLabel||(typeof NAMES!=='undefined'&&NAMES[cb.type])||cb.type;
    const subs=Object.keys(state.topics).filter(t=>{ const m=state.topicMeta[t]; return m&&(m.kind==='main'||(m.kind==='retry'&&(!m.group||m.group===gid))); });
    subs.forEach(t=>{ if(!g.topics[t]) g.topics[t]=Object.fromEntries(state.topics[t].map(p=>[p.index,p.base])); });
    const n=kInstances(cb)*(cb.down?0:1);
    const sig=n+'|'+c.assignor+'|'+subs.join(',');
    if(sig!==g.sig){ kRebalance(state,g,n,subs,g.sig!==''); g.sig=sig; }
  });
  Object.values(state.consumerGroups).forEach(g=>{ if(!seen[g.gid]&&g.members&&g.members.length){ g.members=[]; g.assignment={}; } });
}

// Назначение партиций. members: ['c0','c1',...]; tps: [{t,p}]
function kAssign(strategy,members,tps,prev){
  const out={}; members.forEach(m=>out[m]=[]);
  if(!members.length) return out;
  if(strategy==='roundrobin'){
    tps.slice().sort((a,b)=>a.t<b.t?-1:a.t>b.t?1:a.p-b.p).forEach((tp,i)=>out[members[i%members.length]].push(tp));
    return out;
  }
  if(strategy==='cooperative-sticky' && prev){
    const key=tp=>tp.t+'#'+tp.p, valid=new Set(tps.map(key)), taken=new Set();
    members.forEach(m=>(prev[m]||[]).forEach(tp=>{ if(valid.has(key(tp))&&!taken.has(key(tp))){out[m].push(tp);taken.add(key(tp));} }));
    const free=tps.filter(tp=>!taken.has(key(tp)));
    const target=Math.ceil(tps.length/members.length);
    members.forEach(m=>{ while(out[m].length>target) free.push(out[m].pop()); });
    free.forEach(tp=>{ const m=members.slice().sort((a,b)=>out[a].length-out[b].length)[0]; out[m].push(tp); });
    return out;
  }
  // range: по каждому топику отдельно, первые члены получают «лишние» партиции
  const byT={}; tps.forEach(tp=>(byT[tp.t]=byT[tp.t]||[]).push(tp));
  Object.values(byT).forEach(list=>{
    list.sort((a,b)=>a.p-b.p);
    const per=Math.floor(list.length/members.length), extra=list.length%members.length; let k=0;
    members.forEach((m,i)=>{ const n=per+(i<extra?1:0); for(let j=0;j<n;j++) out[m].push(list[k++]); });
  });
  return out;
}

function kRebalance(state,g,n,subs,isRe){
  const c=state.cfg;
  const members=Array.from({length:n},(_,i)=>g.gid.replace(/-group$/,'')+'-'+(i+1));
  const tps=[]; subs.forEach(t=>state.topics[t].forEach(p=>tps.push({t,p:p.index})));
  const prev=g.assignment;
  const next=kAssign(c.assignor,members,tps,prev);
  g.members=members; g.assignment=next; g.generation++;
  if(isRe){
    state.rebalances++;
    if(c.assignor==='cooperative-sticky'){
      // инкрементальный: стоят только переехавшие партиции
      const owner={}; Object.entries(prev||{}).forEach(([m,l])=>l.forEach(tp=>owner[tp.t+'#'+tp.p]=m));
      g.paused={}; Object.entries(next).forEach(([m,l])=>l.forEach(tp=>{ const k=tp.t+'#'+tp.p; if(owner[k]&&owner[k]!==m) g.paused[k]=2; }));
    } else g.pause=2;   // eager: stop-the-world для всей группы
    kEv(state,{type:'rebalance',gid:g.gid,members:n,eager:c.assignor!=='cooperative-sticky'});
  }
}

// Чтение по оффсету (с учётом дыр после compaction)
function kReadAt(part,off){
  const ms=part.messages; let lo=0,hi=ms.length;
  while(lo<hi){const mid=(lo+hi)>>1; if(ms[mid].offset<off) lo=mid+1; else hi=mid;}
  return lo<ms.length?ms[lo]:null;
}
function kLagPart(part,off){ return Math.max(0, part.hw-Math.max(off||0,part.base)); }

// ── Тик консьюмеров ──
function kafkaTick(b,state){
  const c=state.cfg; state.tick++;
  kafkaSyncGroups(b,state);
  // реплики догоняют лидера → возвращаются в ISR
  Object.values(state.topics).forEach(parts=>parts.forEach(p=>{
    Object.keys(p.catchUp).forEach(r=>{ if(!kUp(state,+r)){delete p.catchUp[r];return;} if(--p.catchUp[r]<=0){ delete p.catchUp[r]; if(!p.isr.includes(+r)) p.isr.push(+r); kRefreshPartition(state,p);} });
  }));
  const failBase=c.delivery==='exactly-once'?0.004:c.delivery==='at-most-once'?0.01:0.02;
  Object.values(state.consumerGroups).forEach(g=>{
    if(!g.members||!g.members.length) return;
    if(g.pause>0){ g.pause--; return; }
    const cb=gb(g.blockId);
    const hl=cb&&cb.rt?cb.rt.health:'ok';
    const factor=(cb&&cb.down)?0:hl==='error'?0.4:hl==='warn'?0.75:1;
    const failP=failBase+(hl==='error'?0.25:0);
    g.members.forEach(m=>{
      let budget=Math.max(0,Math.round(c.pollRate*factor));
      const list=(g.assignment[m]||[]).filter(tp=>{const k=tp.t+'#'+tp.p; if(g.paused[k]>0){g.paused[k]--;return false;} return true;});
      let progress=true;
      while(budget>0&&progress){
        progress=false;
        for(const tp of list){
          if(budget<=0) break;
          const part=state.topics[tp.t]&&state.topics[tp.t][tp.p]; if(!part||part.offline) continue;
          const offs=g.topics[tp.t]||(g.topics[tp.t]={});
          let off=Math.max(offs[tp.p]||0,part.base);
          const msg=kReadAt(part,off); if(!msg) { offs[tp.p]=Math.max(off,part.hw); continue; }
          if(msg.readyTick>state.tick) continue;          // backoff retry-топика (head-of-line)
          budget--; progress=true;
          const ok=Math.random()>=failP;
          if(ok){
            offs[tp.p]=msg.offset+1; g.consumed++; state.totalConsumed++;
            kEv(state,{type:'consumed',gid:g.gid,blockId:g.blockId,member:m,msg});
          } else kFail(b,state,g,m,msg,offs,tp);
        }
      }
    });
  });
}

function kFail(b,state,g,m,msg,offs,tp){
  const c=state.cfg; g.failed++; state.failedCount++;
  if(c.delivery==='at-most-once'){        // оффсет уже закоммичен до обработки → потеря
    offs[tp.p]=msg.offset+1; state.lostCount++;
    kEv(state,{type:'lost',gid:g.gid,blockId:g.blockId,msg}); return;
  }
  if(!c.retryDlq){                        // без retry/DLQ: не коммитим → повторная доставка (дубль)
    state.dupCount++; kEv(state,{type:'redeliver',gid:g.gid,blockId:g.blockId,msg}); return;
  }
  offs[tp.p]=msg.offset+1;
  const base=msg.origTopic||c.topic;
  if((msg.attempt||0)<c.maxRetries){
    const att=(msg.attempt||0)+1;
    // retry-топик — свой у каждой группы (иначе другие группы получили бы дубль)
    kafkaProduce(b,state,{topic:kRetryTopic(base,g.gid),forGroup:g.gid,key:msg.key,value:msg.value,attempt:att,readyTick:state.tick+Math.pow(2,att-1),reqId:msg.reqId,origTopic:base});
    state.retriedCount++;
    kafkaSyncGroups(b,state);
    kEv(state,{type:'retry',gid:g.gid,blockId:g.blockId,msg,attempt:att});
  } else {
    const r=kafkaProduce(b,state,{topic:base+'.dlq',key:msg.key,value:msg.value,attempt:msg.attempt,reqId:msg.reqId,origTopic:base,partition:0});
    state.dlq.push({...msg,failReason:'consumer_error',group:g.gid,dlqAt:Date.now()});
    kEv(state,{type:'dlq',gid:g.gid,blockId:g.blockId,msg,ok:r&&r.ack});
  }
}

// Перезалить DLQ в основной топик (redrive)
function kafkaRedriveDlq(blockId){
  const b=gb(blockId), st=BROKER_STATE[blockId]; if(!b||!st||!st.kafka) return 0;
  let n=0;
  Object.keys(st.topics).filter(t=>st.topicMeta[t]?.kind==='dlq').forEach(t=>{
    const p=st.topics[t][0];
    p.messages.forEach(m=>{ kafkaProduce(b,st,{topic:m.origTopic||st.cfg.topic,key:m.key,value:m.value,attempt:0,reqId:m.reqId}); n++; });
    p.messages=[]; p.base=p.hw;
  });
  st.dlq=[];
  return n;
}

// Достать накопившиеся события (для анимации шариков)
function kafkaDrainEvents(blockId){ const st=BROKER_STATE[blockId]; if(!st||!st.events) return []; const e=st.events; st.events=[]; return e; }

// ── Аналитика для computeFlow: группы, активные/idle консьюмеры, скорость роста лага ──
function kafkaAnnotateFlow(blocks,conns){
  blocks.forEach(b=>{
    if(b.type!=='kafka'||!b.rt) return;
    const c=kafkaCfg(b), lam=b.rt.lambdaIn||0;
    const hot=c.keyStrategy==='hot-key'?kafkaHotShare(c.partitions):1/c.partitions;
    const groups=conns.filter(x=>x.from===b.id).map(x=>blocks.find(y=>y.id===x.to)).filter(Boolean).map(cb=>{
      const inst=kInstances(cb), active=Math.min(inst,c.partitions);
      const perInst=effCap(cb)/inst;
      // самый загруженный консьюмер: тот, кому достался горячий / «лишний» кусок партиций
      const maxShare=Math.max(hot, Math.ceil(c.partitions/active)/c.partitions);
      const thr=Math.min(active*perInst, perInst/Math.max(maxShare,1e-9));
      return {gid:kGroupId(cb), blockId:cb.id, instances:inst, active, idle:inst-active, throughput:Math.round(thr), lagGrowth:Math.max(0,Math.round(lam-thr))};
    });
    b.rt.kafka={topic:c.topic, partitions:c.partitions, rf:c.rf, minIsr:c.minIsr, hotShare:hot, groups, health:kafkaHealth(b)};
    const pp=kafkaPartitionLoad(b,c,lam,groups.map(g=>blocks.find(y=>y.id===g.blockId)));
    b.rt.kafka.parts=pp.parts; b.rt.kafka.hotPart=pp.hotPart; b.rt.kafka.partCap=pp.partCap;
  });
}

// ── Нагрузка по партициям (та же модель, что effCap/kafkaCapMul, только разложенная по P) ──
// λp: hot-key — горячая партиция (hash('celebrity-42')%P, как в симуляции) получает kafkaHotShare(P),
// остальные — поровну; by-entity / null — равномерно. Ёмкость партиции = ёмкость топика без штрафа
// hot-key / P. Лаг: на каждую группу range-назначение партиций членам, член делит свою ёмкость
// между своими партициями; lagGrowth = max(0, λp − скорость чтения), берём худшую группу.
// Если идёт симуляция — добавляем фактический лаг (partLag) из BROKER_STATE.
function kafkaPartitionLoad(b,c,lam,consumers){
  c=c||kafkaCfg(b); const P=c.partitions, rt=b.rt||{};
  const hotKey=c.keyStrategy==='hot-key';
  const h=hotKey?kafkaHotShare(P):1/P;
  const hotIdx=hotKey?Math.abs(hashStr('celebrity-42'))%P:-1;
  const hotMul=hotKey?Math.min(1,1/(P*h)):1;
  const partCap=(rt.cap&&isFinite(rt.cap))?rt.cap/hotMul/P:Infinity;
  const ch=KAFKA_CHAOS[b.id]?.down||{};
  const st=(typeof BROKER_STATE!=='undefined')?BROKER_STATE[b.id]:null;
  const simParts=st&&st.kafka&&st.topics?st.topics[c.topic]:null;
  const parts=[];
  for(let p=0;p<P;p++){
    const share=hotKey?(p===hotIdx?h:(1-KAFKA_HOT_SHARE)/P):1/P;
    const lp=lam*share;
    const offline=kReplicas(p,c).every(r=>ch[r]);
    parts.push({index:p, share, lambda:Math.round(lp), cap:Math.round(partCap), rho:partCap>0&&isFinite(partCap)?lp/partCap:0,
      hot:p===hotIdx, offline, lagGrowth:0, lagGid:null, simLag:null, messages:simParts&&simParts[p]?simParts[p].messages.length:null});
  }
  (consumers||[]).forEach(cb=>{
    if(!cb) return;
    const inst=kInstances(cb), active=Math.min(inst,P), perInst=effCap(cb)/inst;
    const base=Math.floor(P/active), extra=P%active; let p=0;
    for(let m=0;m<active;m++){
      const own=base+(m<extra?1:0), rate=perInst/Math.max(1,own);
      for(let k=0;k<own;k++,p++){ const g=Math.max(0,Math.round(parts[p].lambda-rate));
        if(g>parts[p].lagGrowth){ parts[p].lagGrowth=g; parts[p].lagGid=kGroupId(cb); } }
    }
  });
  if(simParts&&st.consumerGroups) Object.values(st.consumerGroups).forEach(g=>{
    if(!g.members||!g.members.length) return;
    const offs=(g.topics&&g.topics[c.topic])||{};
    parts.forEach(x=>{ const sp=simParts[x.index]; if(!sp) return;
      const l=kLagPart(sp,offs[x.index]); if(x.simLag==null||l>x.simLag) x.simLag=l; });
  });
  return {parts, hotPart:hotIdx, partCap:Math.round(partCap)};
}


;
