let sideTab='analysis';
function switchTab(t){sideTab=t;document.querySelectorAll('.side-tab').forEach(x=>x.classList.toggle('on',x.dataset.tab===t));$('side-analysis').style.display=t==='analysis'?'':'none';$('side-logs').style.display=t==='logs'?'':'none';$('side-routes').style.display=t==='routes'?'':'none';$('side-saves').style.display=t==='saves'?'':'none';if(t==='saves')renderSaves();if(t==='logs')renderLogs();if(t==='routes'&&typeof renderRoutesPanel==='function')renderRoutesPanel();if(S.notationMode==='bpmn'&&t==='analysis'&&typeof renderBpmnPanel==='function')renderBpmnPanel();}
function updateSidebar(){
  const c=$('side-analysis');const sel=gb(S.selected);
  if(sel){
    const d=EL[sel.type];const rt=sel.rt||{};
    let h=`<div style="font-size:13px;font-weight:700;color:var(--txt);margin-bottom:3px">${bLabel(sel)}</div>`;
    h+=`<div style="font-size:11px;color:var(--txt2);margin-bottom:8px;line-height:1.4">${elDesc(sel.type,'role')}</div>`;
    // живые метрики
    if(rt.cap&&isFinite(rt.cap)){
      const pct=Math.round(rt.rho*100);const clr=hClr(rt.health)||'#9ece6a';
      h+=`<div class="metric-box"><div class="metric"><span>${t('an_capacity')}</span><b>${fmt(rt.cap)} rps</b></div><div class="metric"><span>${t('an_load')}</span><b>${fmt(rt.lambdaIn)} rps</b></div><div class="metric"><span>${t('an_usage')}</span><b style="color:${clr}">${pct}%</b></div><div class="metric"><span>${t('an_latency')}</span><b style="color:${clr}">${rt.effLat?.toFixed(1)} ms</b></div></div>`;
      h+=rtExtraHtml(sel);
      if(rt.cbOpen)h+=`<div class="card info">${t('an_cb_open')}</div>`;
      if(rt.cascade)h+=`<div class="card warn">${t('an_cascade')} (${bLabel(gb(rt.slowDueTo))}).</div>`;
      if(rt.health==='error')h+=`<div class="card error">${t('an_overloaded')} ${fixHint(sel)}</div>`;
      else if(rt.health==='warn'&&!rt.cascade)h+=`<div class="card warn">${t('an_warn')} (${pct}%)</div>`;
      else if(rt.health==='ok')h+=`<div class="card ok">${t('an_ok')}</div>`;
    }
    h+=`<div class="info-box">${t('an_place')} ${elDesc(sel.type,'place')}</div>`;
    h+=`<div class="info-box" style="border-color:#f7768e44">${t('an_never')} ${elDesc(sel.type,'never')}</div>`;
    h+=`<div class="card info">💡 ${elDesc(sel.type,'tip')}</div>`;
    if(SETTINGS_DEF[sel.type]){
      const isBroker=['kafka','rabbitmq','nats','queue'].includes(sel.type);
      if(isBroker) h+=`<button onclick="openBrokerInspector('${sel.id}')" style="margin-top:8px;width:100%;padding:7px;border-radius:6px;border:1px solid #bb9af777;background:#bb9af722;color:#bb9af7;cursor:pointer;font-size:11.5px">${t('an_inspector')}${Object.keys(sel.settings||{}).length?t('an_inspector_active'):''}</button>`;
      else h+=`<button onclick="openSettings('${sel.id}')" style="margin-top:8px;width:100%;padding:7px;border-radius:6px;border:1px solid #7aa2f777;background:#7aa2f722;color:#7aa2f7;cursor:pointer;font-size:11.5px">${t('an_where_btn')}${(sel.patterns?.length||Object.keys(sel.settings||{}).length)?t('an_settings_active'):''}</button>`;
    }
    // Топология и модель хранения — для любого типа БД (db-viz.js)
    if(typeof DBV_META!=='undefined'&&DBV_META[sel.type])
      h+=`<button class="dbv-insp-btn" onclick="openDBViz('${sel.id}')">🧬 ${tTask({ru:'Топология и модель хранения',en:'Topology & storage model'})}</button>`;
    // Auth Provider — выбор типа (меняет схему БД и поведение в симуляции)
    if(sel.type==='auth'){
      const at=(typeof authType==='function')?authType(sel):'jwt_only';
      const rate=Math.round(((typeof authPassRate==='function')?authPassRate(sel):0.1)*100);
      const behav={jwt_only:'Stateless: токен по подписи, БД только на login/refresh.',oauth2_jwt:'Токены + интроспекция/refresh.',session_based:'Stateful: КАЖДЫЙ запрос читает сессию из хранилища.'}[at];
      h+=`<div style="margin-top:10px;background:#bb9af714;border-radius:7px;padding:9px">
        <div style="font-size:10px;color:var(--txt);font-weight:700;margin-bottom:5px">🔐 Тип авторизации</div>
        <select onchange="setAuthType('${sel.id}',this.value)" style="width:100%;background:var(--bg3);color:var(--txt);border:1px solid var(--brd2);border-radius:6px;padding:6px;font-size:11.5px;margin-bottom:6px">
          ${[['jwt_only','JWT-only'],['oauth2_jwt','OAuth2 + JWT'],['session_based','Session-based']].map(o=>`<option value="${o[0]}" ${at===o[0]?'selected':''}>${o[1]}</option>`).join('')}
        </select>
        <div style="font-size:10.5px;color:var(--txt2);line-height:1.5">${behav}</div>
        <div style="font-size:10.5px;color:#e0af68;margin-top:5px">Нагрузка на хранилище: <b>${rate}%</b> от трафика${at==='session_based'?' — нужен Redis при росте':''}</div>
      </div>`;
    }
    // Редактор схемы — только для PostgreSQL (реляционная модель)
    if(sel.type==='postgresql'){
      const tblCnt=(typeof schemaTables==='function')?schemaTables(sel).length:0;
      h+=`<button onclick="openDBEditor('${sel.id}')" style="margin-top:6px;width:100%;padding:7px;border-radius:6px;border:1px solid #4a90d977;background:#4a90d922;color:#4a90d9;cursor:pointer;font-size:11.5px">🗄 Редактировать схему${tblCnt?` (${tblCnt} табл.)`:''}</button>`;
      h+=`<button onclick="openDBSchemaPicker('${sel.id}')" style="margin-top:6px;width:100%;padding:7px;border-radius:6px;border:1px solid #4a4c6a;background:transparent;color:#787c99;cursor:pointer;font-size:11px">📚 Загрузить готовую схему</button>`;
    }
    // Redis-редактор паттернов
    if(sel.type==='redis'){
      const pCnt=(sel.redisSchema?.patterns||[]).length;
      h+=`<button onclick="openRedisEditor('${sel.id}')" style="margin-top:6px;width:100%;padding:7px;border-radius:6px;border:1px solid #f7768e77;background:#f7768e18;color:#f7768e;cursor:pointer;font-size:11.5px">⚡ Redis-схема${pCnt?` (${pCnt} паттернов)`:''}</button>`;
    }
    if(typeof zsSidebarHtml==='function')h+=zsSidebarHtml(sel);
    c.innerHTML=h;return;
  }
  // общий список проблем
  const issues=[];
  S.blocks.forEach(b=>{const rt=b.rt||{};const ex=rtIssues(b);if(ex.length){issues.push(...ex);return;}if(rt.health==='error')issues.push({s:'error',n:b.customLabel||EL[b.type].lbl,m:t('an_issue_overload')+' '+Math.round(rt.rho*100)+'% — '+fixHint(b)});else if(rt.cascade)issues.push({s:'warn',n:b.customLabel||EL[b.type].lbl,m:t('an_issue_cascade')});else if(rt.health==='warn')issues.push({s:'warn',n:b.customLabel||EL[b.type].lbl,m:t('an_issue_warn')+' '+Math.round(rt.rho*100)+'%'});});
  Object.entries(S.connWarn||{}).forEach(([cid,w])=>{const c2=gc(cid);if(c2){const f=gb(c2.from);issues.push({s:w.sev,n:(f?.customLabel||EL[f?.type]?.lbl)+'→',m:w.msg});}});
  // структурная проверка брокеров: у брокера/очереди должны быть И продюсер, И консьюмер
  S.blocks.forEach(b=>{const cat=EL[b.type]?.cat;if(cat==='broker'||cat==='queue'){
    const nm=b.customLabel||EL[b.type].lbl;
    const hasProd=S.conns.some(c=>c.to===b.id);
    const consumers=S.conns.filter(c=>c.from===b.id).map(c=>EL[gb(c.to)?.type]?.cat);
    const hasCons=consumers.some(cc=>cc==='svc'||cc==='bff');
    if(!hasProd)issues.push({s:'warn',n:nm,m:t('an_broker_no_prod')+' '+nm});
    if(!S.conns.some(c=>c.from===b.id))issues.push({s:'error',n:nm,m:t('an_broker_no_out')+' '+nm+' '+t('an_broker_to_svc')});
    else if(!hasCons)issues.push({s:'warn',n:nm,m:t('an_broker_no_cons')+' '+nm+' '+t('an_broker_to_svc')});
  }});
  const okCard=S.loadMode==='realism'
    ?(scenTotalRps()===0
        ?`<div class="card warn">${t('an_ok_realism_no_load')}</div>`
        :`<div class="card ok">${t('an_ok_realism')} ${fmt(scenTotalRps())} rps</div>`)
    :`<div class="card ok">${t('an_ok_sandbox')} ${fmt(S.load)} rps</div>`;
  c.innerHTML=!S.blocks.length?`<div style="color:var(--txt2);font-size:11px;line-height:1.7">${typeof t==='function'?t('analyze_empty'):'Перетащи блок из палитры на холст.'}</div>`:!issues.length?okCard:issues.map(i=>`<div class="card ${i.s}"><b>${esc(i.n)}</b><br>${esc(i.m)}</div>`).join('');
}
function fixHint(b){
  const tp=b.type, rt=b.rt||{}, s=b.settings||{}, L=(ru,en)=>tTask({ru,en});
  if(tp==='postgresql'||tp==='mysql'){
    if(rt.connLimited)return L(`лимит соединений: спрос ${rt.connLimited.demand} при max_connections ${rt.connLimited.max} — включи ${tp==='mysql'?'Connection Pool':'PgBouncer'} или уменьши conn_pool сервисов`,`connection limit: demand ${rt.connLimited.demand} vs max_connections ${rt.connLimited.max} — enable ${tp==='mysql'?'Connection Pool':'PgBouncer'} or lower services' conn_pool`);
    if(rt.writeBound||rt.rhoW>=0.9)return L(`реплики не помогут — упираетесь в запись на праймари (${Math.round((rt.wShare||0)*100)}% записи, ${fmt(rt.lambdaWr||0)} из ${fmt(rt.capW||0)} rps): шардируйте, пишите через очередь или снизьте долю записи`,`replicas won't help — the primary is write-bound (${Math.round((rt.wShare||0)*100)}% writes, ${fmt(rt.lambdaWr||0)} of ${fmt(rt.capW||0)} rps): shard, write via a queue or cut the write share`);
    return t('fix_postgresql');
  }
  if(tp==='redis'&&rt.oomErr)return L('noeviction и данные не влезают в maxmemory → записи падают с OOM: увеличь maxmemory или выбери allkeys-LFU/LRU','noeviction and data exceeds maxmemory → writes fail with OOM: raise maxmemory or pick allkeys-LFU/LRU');
  if(['service','bff'].includes(tp))return t('fix_service');
  if(tp==='api_gw')return t('fix_api_gw');
  if(tp==='redis')return t('fix_redis');
  if(tp==='kafka'&&s.key_strategy==='hot-key')return L('смени ключ сообщения (by-entity) — горячая партиция упирается в один лидер, партиции не помогут','change the message key (by-entity) — the hot partition is bound to one leader, partitions won\'t help');
  if(tp==='kafka')return t('fix_kafka');
  if(tp==='rabbitmq')return t('fix_rabbitmq');
  if(tp==='cassandra')return t('fix_cassandra');
  return t('fix_default');
}
function scenTotalRps(){return (S.scenarios||[]).reduce((a,s)=>a+(s.volume||0),0);}
function updateStatus(){
  if(S.notationMode==='bpmn'){ // в BPMN показываем счётчики BPMN, а не C4
    const bp=S.bpmn||{},ds=bp.diagrams||[],d=ds.find(x=>x.id===bp.currentDiagramId)||ds[0]||{elements:[],flows:[]};
    const els=(d.elements||[]).filter(e=>e.type!=='pool'&&e.type!=='lane').length,fl=(d.flows||[]).length;
    $('sb-l').textContent=`BPMN · ${els} ${t('sb_bpmn_els')} · ${fl} ${t('sb_bpmn_flows')}`+(ds.length>1?` · ${t('sb_bpmn_diag')} ${Math.max(1,ds.indexOf(d)+1)}/${ds.length}`:'');
    $('sb-r').textContent=(typeof BPMN_ANIM!=='undefined'&&BPMN_ANIM.running)?'▶ BPMN':'';
    return;
  }
  $('sb-l').textContent=(typeof zsStatusPrefix==='function'?zsStatusPrefix():'')+`${S.blocks.length} ${t('sb_blocks')} · ${S.conns.length} ${t('sb_connections')}`+((S.scenarios&&S.scenarios.length)?` · ${S.scenarios.length} ${t('sb_scenarios')}`:'');
  const loadTxt=S.loadMode==='realism'?('Σ '+fmt(scenTotalRps())+' rps ('+t('sb_realism')+')'):(fmt(S.load)+' rps');
  $('sb-r').textContent=loadTxt+(SIM.running?(SIM.paused?' ⏸':' ▶ '+Object.keys(SIM.dots).length+' '+t('sb_balls')):'');
}
function setLoad(l){S.load=l;const inp=$('load-input');if(inp&&document.activeElement!==inp)inp.value=fmt(l);analyze();}
function setLoadMode(m){
  S.loadMode=m;
  document.querySelectorAll('.modebtn').forEach(b=>b.classList.toggle('on',b.dataset.m===m));
  const li=$('load-input');if(li){li.disabled=(m==='realism');li.style.opacity=(m==='realism')?'0.4':'1';}
  if(m==='realism'&&!(S.scenarios&&S.scenarios.length))toast(t('toast_realism_no_scenarios'),3500);
  analyze();
}
// разбор ввода: "1.5M","200k","50 000","2кк" → число
function parseLoad(str){
  if(typeof str==='number')return str;
  let s=String(str).trim().toLowerCase().replace(/[\s_]/g,'').replace(',','.').replace('×','').replace('x','');
  let mult=1;
  const m=s.match(/(к|k|тыс)+$/)?1e3:0;
  if(/(млрд|b|g)$/.test(s)){mult=1e9;s=s.replace(/(млрд|b|g)$/,'');}
  else if(/(млн|m|кк|кк)$/.test(s)){mult=1e6;s=s.replace(/(млн|m|кк)$/,'');}
  else if(/(к|k|тыс)$/.test(s)){mult=1e3;s=s.replace(/(к|k|тыс)$/,'');}
  const n=parseFloat(s);
  if(!isFinite(n)||n<0)return null;
  return Math.round(n*mult);
}
function applyLoadInput(){
  const inp=$('load-input');if(!inp)return;
  const n=parseLoad(inp.value);
  if(n===null||n<1){inp.value=fmt(S.load);toast('Введи число, напр. 50000 или 1.5M');return;}
  const v=Math.min(n,1e12);
  setLoad(v);inp.value=fmt(v);
}
function bumpLoad(dir){const v=dir>0?S.load*10:Math.max(1,Math.round(S.load/10));setLoad(v);$('load-input').value=fmt(v);}
function toggleEdgeStyle(){
  S.edgeStyle=(S.edgeStyle||'ortho')==='ortho'?'curved':'ortho';
  const b=$('edge-btn');if(b)b.textContent=S.edgeStyle==='ortho'?t('edge_style_ortho'):t('edge_style_curve');
  render();
}
function clearAll(){if(S.blocks.length&&!confirm(t('confirm_clear')))return;stopSim();S.blocks=[];S.conns=[];S.scenarios=[];S.selected=null;pushHist();analyze();if(typeof renderRoutesPanel==='function')renderRoutesPanel();}

// ═══════════════════════════════════════════════════════════════
// РЕДАКТОР МЕТАДАННЫХ СИСТЕМЫ («О системе» — титул, роли, требования)
// ═══════════════════════════════════════════════════════════════
function openMetaEditor(){
  ensureMeta();
  let ov=$('meta-modal');
  if(!ov){
    ov=document.createElement('div');ov.id='meta-modal';ov.className='modal-ov';
    ov.onclick=e=>{if(e.target===ov)closeMetaEditor();};
    document.body.appendChild(ov);
  }
  ov.style.display='flex';renderMetaEditor();
}
function closeMetaEditor(){const ov=$('meta-modal');if(ov)ov.style.display='none';pushHist();analyze();}
function renderMetaEditor(){
  const m=S.meta;const ov=$('meta-modal');if(!ov)return;
  const inp='background:#faf4e8;border:1px solid #7a6e5a;padding:6px 8px;font-size:12px;color:#1a1410;outline:none;font-family:inherit;width:100%';
  const lbl='display:block;font-size:10px;color:#6a6050;margin-bottom:3px;font-weight:600;text-transform:uppercase;letter-spacing:.05em';
  const sec=(icon,txt,clr)=>`<div style="font-size:11px;font-weight:700;color:${clr||'#162850'};margin:14px 0 6px;padding-bottom:4px;border-bottom:1px solid #7a6e5a44">${icon} ${txt}</div>`;
  const DOMAINS=['','E-commerce','Fintech','EdTech','Healthcare','Logistics','SaaS / B2B','Маркетплейс','Медиа / Стриминг','Социальная сеть','Другое'];
  ov.innerHTML=`<div class="modal-box" style="max-width:680px;width:96%;background:#d8d0be;border:2px solid #7a6e5a">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px">
      <h2 style="color:#162850;font-size:15px">${t('meta_title')}</h2>
      <button class="modal-btn" onclick="closeMetaEditor()">✕</button>
    </div>

    ${sec('🏷',t('meta_sec_ident'))}
    <div style="display:grid;grid-template-columns:2fr 1fr 1fr;gap:8px;margin-bottom:10px">
      <div><label style="${lbl}">${t('meta_sys_name')}</label><input id="meta-name" style="${inp}" value="${escHtml(m.systemName||'')}" placeholder="${t('meta_sys_name_ph')}"></div>
      <div><label style="${lbl}">${t('meta_version')}</label><input id="meta-ver" style="${inp}" value="${escHtml(m.version||'')}" placeholder="${t('meta_version_ph')}"></div>
      <div><label style="${lbl}">${t('meta_author')}</label><input id="meta-author" style="${inp}" value="${escHtml(m.author||'')}" placeholder="${t('meta_author_ph')}"></div>
    </div>
    <div style="margin-bottom:10px"><label style="${lbl}">${t('meta_domain')}</label>
      <select id="meta-domain" style="${inp}">
        ${DOMAINS.map(d=>`<option value="${d}"${(m.domain||'')==d?' selected':''}>${d||t('meta_domain_ph')}</option>`).join('')}
      </select>
    </div>

    ${sec('🎯',t('meta_sec_essence'),'#1e4a90')}
    <div style="margin-bottom:8px"><label style="${lbl}">${t('meta_problem')}</label>
      <textarea id="meta-problem" style="${inp};min-height:56px;resize:vertical" placeholder="${t('meta_problem_ph')}">${escHtml(m.problem||'')}</textarea></div>
    <div style="margin-bottom:8px"><label style="${lbl}">${t('meta_solution')}</label>
      <textarea id="meta-solution" style="${inp};min-height:56px;resize:vertical" placeholder="${t('meta_solution_ph')}">${escHtml(m.solution||'')}</textarea></div>
    <div style="margin-bottom:10px"><label style="${lbl}">${t('meta_desc')}</label>
      <textarea id="meta-desc" style="${inp};min-height:48px;resize:vertical" placeholder="${t('meta_desc_ph')}">${escHtml(m.description||'')}</textarea></div>

    ${sec('👥',t('meta_sec_users'),'#2a6010')}
    <div id="meta-roles">${(m.userRoles||[]).map((r,ri)=>`
      <div style="border:1px solid #7a6e5a44;padding:8px;margin-bottom:6px;background:#ccc4b0">
        <div style="display:flex;gap:6px;margin-bottom:5px">
          <input style="${inp}" value="${escHtml(r.name)}" placeholder="${t('meta_role_name_ph')}" onchange="S.meta.userRoles[${ri}].name=this.value">
          <button class="modal-btn" onclick="S.meta.userRoles.splice(${ri},1);renderMetaEditor()" style="color:#8a1808;padding:4px 8px">✕</button>
        </div>
        <textarea style="${inp};min-height:48px;resize:vertical" placeholder="${t('meta_role_can_ph')}" onchange="S.meta.userRoles[${ri}].can=this.value.split('\\n').map(s=>s.trim()).filter(Boolean)">${esc((r.can||[]).join('\n'))}</textarea>
      </div>`).join('')}</div>
    <button class="modal-btn" onclick="S.meta.userRoles.push({name:'${t('meta_new_role')}',can:[]});renderMetaEditor()" style="margin-bottom:12px">${t('meta_add_role')}</button>

    ${sec('📐',t('meta_sec_reqs'),'#7a5008')}
    <div id="meta-reqs">${(m.requirements||[]).map((r,ri)=>`
      <div style="display:flex;gap:6px;margin-bottom:5px">
        <input style="${inp};flex:1" value="${escHtml(r.text)}" placeholder="${t('meta_req_text_ph')}" onchange="S.meta.requirements[${ri}].text=this.value">
        <input style="${inp};width:70px" value="${escHtml(r.card||'')}" placeholder="${t('meta_req_card_ph')}" onchange="S.meta.requirements[${ri}].card=this.value">
        <button class="modal-btn" onclick="S.meta.requirements.splice(${ri},1);renderMetaEditor()" style="color:#8a1808;padding:4px 8px">✕</button>
      </div>`).join('')}</div>
    <button class="modal-btn" onclick="S.meta.requirements.push({text:'',card:''});renderMetaEditor()">${t('meta_add_req')}</button>

    <div style="margin-top:16px;display:flex;gap:8px">
      <button class="modal-btn primary" onclick="saveMetaFields();closeMetaEditor()">${t('meta_done')}</button>
      <button class="modal-btn" onclick="closeMetaEditor()">${t('meta_cancel')}</button>
    </div>
  </div>`;
}
function saveMetaFields(){
  const g=id=>$(id)?.value||'';
  S.meta.systemName=g('meta-name');S.meta.version=g('meta-ver');
  S.meta.author=g('meta-author');S.meta.description=g('meta-desc');
  S.meta.domain=g('meta-domain');S.meta.problem=g('meta-problem');S.meta.solution=g('meta-solution');
}


// ── Метрики движка для БД/Redis: вкладка «Анализ», тултип блока ──
// Redis: hit rate (с учётом переполнения памяти), заполнение, OOM. PostgreSQL/MySQL: запись/чтение, праймари, реплики, лаг.
function rtExtraRows(b){
  const rt=b.rt||{}, s=b.settings||{}, L=(ru,en)=>tTask({ru,en}), rows=[];
  if(b.type==='redis'&&rt.hitRate!=null){
    const base=(s.hit_rate!=null&&s.hit_rate!==''?+s.hit_rate:80), h=Math.round(rt.hitRate*100);
    rows.push({k:'Hit rate',v:h+'%'+(h<Math.round(base)?' ('+L('настройка','set')+' '+Math.round(base)+'%)':''),c:h<Math.round(base)-5?'warn':null,id:'hit'});
    const fill=(typeof redisFill==='function')?redisFill(b):0;
    rows.push({k:L('Память','Memory'),v:(s.dataset||'512mb')+' / '+(s.maxmemory||'1gb')+' · '+Math.round(fill*100)+'%',c:fill>1?(rt.oomErr?'error':'warn'):null,id:'mem'});
    if(rt.oomErr)rows.push({k:'OOM',v:Math.round(rt.oomErr*100)+'% '+L('запросов','requests'),c:'error',id:'oom'});
  }
  if((b.type==='postgresql'||b.type==='mysql')&&rt.capW!=null){
    const ws=Math.round((rt.wShare||0)*100);
    rows.push({k:L('Запись / чтение','Write / read'),v:ws+'% / '+(100-ws)+'% · '+fmt(rt.lambdaWr||0)+' w rps',id:'ws'});
    rows.push({k:L('Праймари (запись)','Primary (writes)'),v:fmt(rt.capW)+' rps · '+Math.round((rt.rhoW||0)*100)+'%',c:rt.rhoW>=0.9?'error':rt.rhoW>=0.6?'warn':null,id:'pw'});
    if(+s.replicas>0){
      rows.push({k:L('Чтение (+'+s.replicas+' реплик)','Reads (+'+s.replicas+' replicas)'),v:fmt(rt.capR)+' rps',id:'rr'});
      rows.push({k:L('Лаг реплик','Replica lag'),v:(rt.replLag>=5000?'> 5 s':rt.replLag+' ms'),c:rt.replLag>=1000?'error':rt.replLag>=200?'warn':null,id:'lag'});
    }
  }
  return rows;
}
// Kafka: нагрузка по партициям (rt.kafka.parts из kafkaAnnotateFlow) — λ, ρ, горячая партиция, лаг консьюмеров
function kafkaPartsHtml(b){
  const k=b.rt&&b.rt.kafka; if(!k||!k.parts||!k.parts.length)return '';
  const L=(ru,en)=>tTask({ru,en}), P=k.parts.length, MAX=16;
  const sev=r=>r>=0.9?'err':r>=0.6?'warn':'ok';
  let list=k.parts.slice();
  if(P>MAX){ list.sort((x,y)=>y.rho-x.rho||x.index-y.index); list=list.slice(0,MAX-1).sort((x,y)=>x.index-y.index); }
  const sim=k.parts.some(x=>x.simLag!=null);
  const lagTxt=x=>x.offline?'offline':(x.lagGrowth>0?'+'+fmt(x.lagGrowth):'0')+(sim?' · '+(x.simLag||0):'');
  let h=`<div class="kp-box" data-k="kparts"><div class="kp-h">${L('Партиции топика','Topic partitions')} <b>${esc(k.topic)}</b> · ${P} × ${fmt(k.partCap)} rps</div>`;
  h+=`<div class="kp-row kp-hdr"><span>P</span><span>${L('загрузка','load')}</span><span>λ rps</span><span title="${L('рост лага (модель) · текущий лаг в сообщениях (симуляция)','lag growth (model) · current lag in messages (simulation)')}">${sim?'Δ/s · msg':L('лаг Δ/s','lag Δ/s')}</span></div>`;
  h+=list.map(x=>{const pct=Math.round(x.rho*100), w=Math.min(100,pct);
    return `<div class="kp-row${x.hot?' kp-hot':''}${x.offline?' kp-off':''}" data-p="${x.index}"><span>P${x.index}${x.hot?' 🔥':''}</span><span class="kp-bar"><i class="kp-${sev(x.rho)}" style="width:${w}%"></i><em>${pct}%</em></span><span>${fmt(x.lambda)}</span><span class="${x.lagGrowth>0?'kp-lag':''}">${lagTxt(x)}</span></div>`;}).join('');
  if(P>MAX)h+=`<div class="kp-more">${L('показаны '+(MAX-1)+' самых загруженных из '+P,'showing top '+(MAX-1)+' of '+P)}</div>`;
  const hot=k.hotPart>=0?k.parts[k.hotPart]:null;
  if(hot)h+=`<div class="kp-note kp-n-${sev(hot.rho)}">🔥 ${L('Горячая партиция P'+hot.index+': '+Math.round(hot.share*100)+'% трафика, '+Math.round(hot.rho*100)+'% её ёмкости. Новые партиции её не разгрузят — смените ключ (by-entity) или солите горячий ключ.','Hot partition P'+hot.index+': '+Math.round(hot.share*100)+'% of traffic, '+Math.round(hot.rho*100)+'% of its capacity. More partitions won\'t help — change the key (by-entity) or salt the hot key.')}</div>`;
  const lagP=k.parts.filter(x=>x.lagGrowth>0);
  if(lagP.length){
    const g=(k.groups||[]).find(x=>x.gid===lagP[0].lagGid), full=g&&g.instances>=P, pl=lagP.map(x=>'P'+x.index).join(', ');
    const fix=hot&&lagP.length===1&&lagP[0].hot?L('разгрузите горячую партицию (смените ключ)','relieve the hot partition (change the key)')
      :full?L('реплик уже ≥ партиций (лишние простаивают) — добавьте партиций или ускорьте консьюмер','replicas ≥ partitions already (extra ones idle) — add partitions or speed up the consumer')
      :L('добавьте консьюмеру реплик (до '+P+' — по числу партиций)','add consumer replicas (up to '+P+' — one per partition)');
    h+=`<div class="kp-note kp-n-warn">⏳ ${L('Лаг растёт на '+pl+' (группа '+lagP[0].lagGid+'): консьюмер не успевает читать — ','Lag grows on '+pl+' (group '+lagP[0].lagGid+'): the consumer can\'t keep up — ')+fix}.</div>`;
  }
  return h+'</div>';
}
function rtExtraHtml(b){
  if(b.type==='kafka')return kafkaPartsHtml(b);
  const rows=rtExtraRows(b); if(!rows.length)return '';
  const clr=c=>c==='error'?'#c0392b':c==='warn'?'#a86400':'';
  let h='<div class="metric-box rt-extra">'+rows.map(r=>`<div class="metric" data-k="${r.id}"><span>${esc(r.k)}</span><b${r.c?` style="color:${clr(r.c)}"`:''}>${esc(r.v)}</b></div>`).join('')+'</div>';
  const rt=b.rt||{}, L=(ru,en)=>tTask({ru,en});
  if(rt.writeBound)h+=`<div class="card warn rt-wb">📝 ${L('Упор в запись: реплики ускоряют только чтение, а запись идёт на праймари. Ещё реплики не помогут — шардируйте или снизьте долю записи.','Write-bound: replicas speed up reads only, writes go to the primary. More replicas won\'t help — shard or cut the write share.')}</div>`;
  if(rt.replLag>=200)h+=`<div class="card warn rt-lag">⏳ ${L('Реплики отстают ('+(rt.replLag>=5000?'> 5 с':rt.replLag+' мс')+'): чтение с реплик может вернуть устаревшие данные (read-your-writes — читать с праймари).','Replicas lag ('+(rt.replLag>=5000?'> 5 s':rt.replLag+' ms')+'): replica reads may be stale (read-your-writes — read from the primary).')}</div>`;
  if(b.type==='redis'&&rt.hitRate!=null){const fill=(typeof redisFill==='function')?redisFill(b):0;
    if(rt.oomErr)h+=`<div class="card error rt-oom">💥 ${fixHint(b)}</div>`;
    else if(fill>1)h+=`<div class="card warn rt-evict">♻ ${L('Данные не влезают в maxmemory — вытеснение снижает hit rate, больше промахов уходит в БД.','Data exceeds maxmemory — eviction lowers the hit rate, more misses reach the DB.')}</div>`;}
  return h;
}
function rtTipText(b){
  const rt=b.rt||{}, d=EL[b.type]||{}, lines=[(b.customLabel||d.lbl||b.type)];
  if(rt.cap&&isFinite(rt.cap))lines.push(`${fmt(rt.lambdaIn||0)} / ${fmt(rt.cap)} rps · ${Math.round((rt.rho||0)*100)}%`);
  rtExtraRows(b).forEach(r=>lines.push(r.k+': '+r.v));
  return lines.join('\n');
}
// Доп. проблемы для общего списка «Анализ» (вместо безликого «перегрузка N%»)
function rtIssues(b){
  const rt=b.rt||{}, n=b.customLabel||EL[b.type]?.lbl, L=(ru,en)=>tTask({ru,en}), out=[];
  if(b.type==='redis'&&rt.oomErr)out.push({s:'error',n,m:'OOM '+Math.round(rt.oomErr*100)+'% — '+fixHint(b)});
  else if(b.type==='redis'&&rt.hitRate!=null&&typeof redisFill==='function'&&redisFill(b)>1&&rt.health!=='error')out.push({s:'warn',n,m:L('hit rate упал до ','hit rate dropped to ')+Math.round(rt.hitRate*100)+'% — '+L('данные не влезают в maxmemory','data exceeds maxmemory')});
  if(b.type==='kafka'&&rt.kafka&&rt.kafka.parts){
    const k=rt.kafka, hot=k.hotPart>=0?k.parts[k.hotPart]:null, lagP=k.parts.filter(x=>x.lagGrowth>0);
    if(hot&&hot.rho>=0.6)out.push({s:hot.rho>=0.9?'error':'warn',n,m:L('горячая партиция P','hot partition P')+hot.index+' — '+Math.round(hot.share*100)+L('% трафика, загрузка ','% of traffic, load ')+Math.round(hot.rho*100)+'%'});
    else if(rt.health==='error')out.push({s:'error',n,m:t('an_issue_overload')+' '+Math.round(rt.rho*100)+'% — '+fixHint(b)});
    if(lagP.length)out.push({s:'warn',n,m:L('лаг консьюмеров растёт на ','consumer lag grows on ')+lagP.map(x=>'P'+x.index).join(', ')+' ('+lagP[0].lagGid+')'});
  }
  if((b.type==='postgresql'||b.type==='mysql')&&rt.health==='error')out.push({s:'error',n,m:t('an_issue_overload')+' '+Math.round(rt.rho*100)+'% — '+fixHint(b)});
  else if((b.type==='postgresql'||b.type==='mysql')&&rt.replLag>=200)out.push({s:'warn',n,m:L('лаг реплик ','replica lag ')+(rt.replLag>=5000?'> 5 s':rt.replLag+' ms')+L(' — праймари перегружен записью',' — primary is write-saturated')});
  return out;
}


;
// ===== sim-trace.js =====
// SIM-TRACE — детальная трассировка запросов: SQL/Redis/брокер, hover-тултип, таймлайн
// Загружается ДО sim.js; использует gb, EL, BASE, baseLat из engine/catalog/core.

function _esc(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

// ── SQL-запрос по схеме БД и методу ──────────────────────────────
function genSQLQuery(dbBlock, verb, connMethod){
  const schema = dbBlock.dbSchema;
  const tables = schema?.tables || schema?.collections || [];
  const t0 = tables[0];
  const raw = dbBlock.customLabel || EL[dbBlock.type]?.lbl || 'records';
  const tableName = t0?.name || raw.toLowerCase().replace(/\s+/g,'_').replace(/[^a-z0-9_]/g,'');
  const cols = (t0?.fields || []).slice(0, 6);
  const pkField = cols.find(f => /\bPK\b/i.test(f.constraints||''))?.name || 'id';
  const colNames = cols.length ? cols.map(f => f.name).join(', ') : '*';
  const uri = connMethod?.uri || '';
  const params = connMethod?.params || [];
  const bodyParams = params.filter(p => p.in === 'body' || !p.in);
  verb = verb || 'GET';

  if(verb === 'GET'){
    if(/:id|{id}|\$/.test(uri)){
      return `SELECT ${colNames}\nFROM ${tableName}\nWHERE ${pkField} = $1\nLIMIT 1`;
    }
    const filterCol = cols.find(f => /\bNN\b/i.test(f.constraints||'') && !/\bPK\b/i.test(f.constraints||''));
    if(filterCol){
      return `SELECT ${colNames}\nFROM ${tableName}\nWHERE ${filterCol.name} = $1\nORDER BY ${pkField} DESC\nLIMIT 20`;
    }
    return `SELECT ${colNames}\nFROM ${tableName}\nORDER BY ${pkField} DESC\nLIMIT 20`;
  }
  if(verb === 'POST'){
    const ins = bodyParams.length ? bodyParams.slice(0,5)
      : cols.filter(f => !/\bPK\b/i.test(f.constraints||'')).slice(0,4);
    if(!ins.length) return `INSERT INTO ${tableName} DEFAULT VALUES\nRETURNING ${pkField}`;
    const names = ins.map(p => p.name||p).join(', ');
    const vals  = ins.map((_,i) => `$${i+1}`).join(', ');
    return `INSERT INTO ${tableName} (${names})\nVALUES (${vals})\nRETURNING ${pkField}`;
  }
  if(verb === 'PUT' || verb === 'PATCH'){
    const upd = bodyParams.length ? bodyParams.slice(0,4)
      : cols.filter(f => !/\bPK\b/i.test(f.constraints||'')).slice(0,3);
    const sets = upd.length ? upd.map((p,i) => `${p.name||p} = $${i+1}`).join(',\n       ')
                            : 'updated_at = NOW()';
    const pNum = upd.length + 1;
    return `UPDATE ${tableName}\nSET ${sets}\nWHERE ${pkField} = $${pNum}\nRETURNING ${pkField}`;
  }
  if(verb === 'DELETE'){
    return `DELETE FROM ${tableName}\nWHERE ${pkField} = $1\nRETURNING ${pkField}`;
  }
  return `SELECT ${colNames}\nFROM ${tableName}\nLIMIT 1`;
}

// ── Redis-команда ─────────────────────────────────────────────────
function genRedisCmd(cacheBlock, verb, connMethod){
  const uri = connMethod?.uri || '';
  const parts = uri.split('/').filter(p => p && !p.startsWith(':') && !p.startsWith('{') && !/^v\d/.test(p));
  const resource = parts[parts.length-1] || 'item';
  const key = `${resource}:{id}`;
  const ttl = cacheBlock.settings?.ttl || 3600;
  verb = verb || 'GET';
  if(verb === 'GET')    return `GET ${key}`;
  if(verb === 'DELETE') return `DEL ${key}`;
  return `SET ${key} "{...json}" EX ${ttl}`;
}

// ── Команда брокера ───────────────────────────────────────────────
function genBrokerCmd(brokerBlock, verb, connMethod){
  const uri = connMethod?.uri || '';
  const parts = uri.split('/').filter(p => p && !p.startsWith(':') && !p.startsWith('{') && !/^v\d/.test(p));
  const resource = parts[parts.length-1] || 'events';
  const evMap = {POST:'created',PUT:'updated',PATCH:'updated',DELETE:'deleted',GET:'read'};
  const evType = evMap[verb||'POST'] || 'event';
  const topic = `${resource}.${evType}`;
  if(brokerBlock.type === 'kafka'){
    const numParts = brokerBlock.settings?.partitions || 3;
    return `produce(topic="${topic}"\n  key="{id}", partition=auto/${numParts}\n  payload={...event data})`;
  }
  if(brokerBlock.type === 'rabbitmq'){
    return `AMQP publish(exchange="${resource}"\n  routingKey="${evType}"\n  body={...event data})`;
  }
  return `publish(queue="${topic}"\n  msg={type:"${evType}", ...})`;
}

// ── Симулированный ответ ──────────────────────────────────────────
function genSimResponse(toBlock, verb, status){
  const cat = EL[toBlock?.type]?.cat;
  if(status === 'fail'){
    return ['500 Internal Server Error','503 Service Unavailable','408 Timeout','502 Bad Gateway'][Math.floor(Math.random()*4)];
  }
  if(cat === 'db'){
    const schema = toBlock.dbSchema;
    const t0 = schema?.tables?.[0];
    const pkField = t0?.fields?.find(f => /\bPK\b/i.test(f.constraints||''))?.name || 'id';
    switch(verb||'GET'){
      case 'GET':    return `200 · ${Math.floor(Math.random()*15)+1} row(s) fetched`;
      case 'POST':   return `201 Created · ${pkField}=${Math.floor(Math.random()*89999)+10000}`;
      case 'PUT':
      case 'PATCH':  return '200 · 1 row updated';
      case 'DELETE': return '204 · 1 row deleted';
      default:       return '200 OK';
    }
  }
  if(cat === 'cache'){
    if(verb === 'GET') return Math.random() < 0.72 ? 'HIT · {cached data}' : 'MISS → fallback to DB';
    return 'OK';
  }
  if(cat === 'broker' || cat === 'queue'){
    return `ACK · offset=${Math.floor(Math.random()*999)+1}`;
  }
  switch(verb||'GET'){
    case 'POST':   return '201 Created';
    case 'DELETE': return '204 No Content';
    case 'PUT':
    case 'PATCH':  return '200 OK (updated)';
    default:       return '200 OK';
  }
}

// ── Построить hop-event ───────────────────────────────────────────
function buildHopEvent(fromId, toId, conn, isResponse){
  const fromB = (typeof gb==='function') ? gb(fromId) : null;
  const toB   = (typeof gb==='function') ? gb(toId)   : null;
  if(!fromB || !toB) return null;

  const cat  = EL[toB.type]?.cat;
  const verb = conn?.method?.verb || (isResponse ? null : 'GET');
  const method = conn?.method ? (typeof fmtMethod==='function' ? fmtMethod(conn.method) : null) : null;
  const latMs  = +((toB.rt?.effLat || (typeof baseLat==='function' ? baseLat(toB) : 5))).toFixed(1);
  const status = toB.rt?.health === 'error' ? 'fail' : toB.rt?.health === 'warn' ? 'slow' : 'ok';

  let query = null, queryType = null, icon = '→';
  if(!isResponse){
    if(cat === 'db'){
      query = genSQLQuery(toB, verb, conn?.method);
      queryType = 'sql';  icon = '🗄';
    } else if(cat === 'cache'){
      query = genRedisCmd(toB, verb, conn?.method);
      queryType = 'redis'; icon = '⚡';
    } else if(cat === 'broker' || cat === 'queue'){
      query = genBrokerCmd(toB, verb, conn?.method);
      queryType = 'broker'; icon = '📨';
    }
  }

  const resp = conn?.method?.resp || conn?.respLabel ||
    (isResponse ? genSimResponse(fromB, verb, status) : null);

  return {
    fromId, toId,
    fromLabel: fromB.customLabel || EL[fromB.type]?.lbl || fromId,
    toLabel:   toB.customLabel   || EL[toB.type]?.lbl   || toId,
    method, verb, query, queryType, icon, latMs, status, resp, isResponse,
    t: Date.now(),
  };
}

// Вызывается из sim.js при каждом шаге запроса
function recordHop(req, fromId, toId, conn){
  if(!req.hopTrace) req.hopTrace = [];
  const ev = buildHopEvent(fromId, toId, conn, !!req.isResponse);
  if(ev) req.hopTrace.push(ev);
}

// ── HOVER-ТУЛТИП ─────────────────────────────────────────────────
let _htip = null;
function showHoverTip(reqId, cx, cy){
  if(!SIM || !SIM.reqs) return;
  const req = SIM.reqs[reqId] || (typeof PSIM!=='undefined' && PSIM.parked[reqId]); if(!req) return;
  if(!_htip){
    _htip = document.createElement('div');
    _htip.id = 'sim-hover-tip';
    _htip.style.cssText = 'position:fixed;pointer-events:none;z-index:9999;background:#1a1b26ee;backdrop-filter:blur(6px);border:1.5px solid #3d3f52;border-radius:10px;padding:9px 12px;font-size:11px;color:#c0caf5;max-width:270px;box-shadow:0 4px 22px #0009;line-height:1.55';
    document.body.appendChild(_htip);
  }
  const curId  = req.path[req.idx-1] || req.path[0];
  const nextId = req.path[req.idx];
  const curB   = (typeof gb==='function') ? gb(curId)  : null;
  const nextB  = (typeof gb==='function') && nextId ? gb(nextId) : null;
  const lastH  = req.hopTrace?.[req.hopTrace.length-1];
  const stClr  = req.dead ? '#f7768e' : req.color === '#e0af68' ? '#e0af68' : '#9ece6a';

  let h = `<div style="font-weight:700;color:#7aa2f7;margin-bottom:4px">${req.isResponse?'▶ Ответ':'● Запрос'} #${req.id.slice(1)}</div>`;
  h += `<div style="color:#9aa5ce;font-size:10.5px">📍 ${_esc(curB?.customLabel||EL[curB?.type]?.lbl||'?')} <span style="color:#4a4c6a">→</span> <b>${nextB?_esc(nextB.customLabel||EL[nextB.type]?.lbl):'конец'}</b></div>`;
  if(lastH?.method) h += `<div style="color:#7aa2f7;font-size:10.5px;margin-top:2px">⚙ ${_esc(lastH.method)}</div>`;
  if(lastH?.pats?.length) h += `<div style="color:#bb9af7;font-size:10.5px;margin-top:2px">🧩 ${_esc(lastH.pats[lastH.pats.length-1])}</div>`;
  if(lastH?.query){
    const firstLine = lastH.query.split('\n')[0];
    const preview   = firstLine.length > 46 ? firstLine.slice(0,46)+'…' : firstLine;
    const qc = lastH.queryType==='sql'?'#7dcfff':lastH.queryType==='redis'?'#9ece6a':'#bb9af7';
    h += `<div style="margin-top:4px;font-family:Consolas,monospace;font-size:10px;color:${qc};background:#11121a;padding:3px 7px;border-radius:5px;white-space:nowrap;overflow:hidden">${_esc(preview)}</div>`;
  }
  if(lastH?.resp){
    const rc = /^2/.test(lastH.resp)||lastH.resp==='OK'||/HIT|ACK/.test(lastH.resp) ? '#9ece6a' : '#f7768e';
    h += `<div style="margin-top:3px;font-size:10px;color:${rc}">↩ ${_esc(lastH.resp)}</div>`;
  }
  h += `<div style="margin-top:5px;display:flex;justify-content:space-between;align-items:center">`;
  h += `<span style="font-size:10.5px;color:${stClr}">${req.dead?'❌ Упадёт':req.color==='#e0af68'?'⚠ Медленно':'✓ Норма'}</span>`;
  h += `<span style="font-size:10.5px;color:#e0af68"><b>${req.accLat.toFixed(0)} мс</b></span>`;
  h += `</div>`;
  h += `<div style="font-size:9.5px;color:#4a4c6a;margin-top:3px;text-align:right">клик → полный трейс</div>`;

  _htip.innerHTML = h;
  _htip.style.display = 'block';
  const tw = _htip.offsetWidth, th2 = _htip.offsetHeight;
  const vw = window.innerWidth,  vh  = window.innerHeight;
  let lx = cx + 16, ly = cy - 14;
  if(lx + tw  > vw - 8) lx = cx - tw  - 12;
  if(ly + th2 > vh - 8) ly = cy - th2 - 8;
  _htip.style.left = lx + 'px';
  _htip.style.top  = ly + 'px';
}
function hideHoverTip(){ if(_htip) _htip.style.display = 'none'; }

// ── ТАЙМЛАЙН в модалке ────────────────────────────────────────────
function renderTraceTimeline(req){
  const trace = req.hopTrace || [];
  if(!trace.length) return '<div style="color:var(--txt2);font-size:11px;padding:8px 0">Трассировка пуста — запрос ещё не прошёл ни одного узла.</div>';

  const rows = trace.map((h, i) => {
    const isLast = i === trace.length - 1;
    const sc = h.status==='fail'?'#f7768e':h.status==='slow'?'#e0af68':'#9ece6a';
    const si = h.status==='fail'?'❌':h.status==='slow'?'⚠':'✓';

    let qHtml = '';
    if(h.query){
      const qc = h.queryType==='sql'?'#7dcfff':h.queryType==='redis'?'#9ece6a':'#bb9af7';
      const ql = h.queryType==='sql'?'SQL':h.queryType==='redis'?'Redis':'Broker';
      qHtml += `<div style="margin-top:5px;background:#11121a;border-radius:6px;padding:6px 9px;font-family:Consolas,monospace;font-size:10px;color:${qc};white-space:pre-wrap;border-left:2px solid ${qc}"><span style="opacity:.55;font-size:9.5px">${ql}:</span>\n${_esc(h.query)}</div>`;
    }
    if(h.resp){
      const rc = /^2/.test(h.resp)||h.resp==='OK'||/HIT|ACK/.test(h.resp) ? '#9ece6a'
                 : /^[45]/.test(h.resp) ? '#f7768e' : '#e0af68';
      qHtml += `<div style="margin-top:4px;font-size:10.5px;color:${rc}">↩ ${_esc(h.resp)}</div>`;
    }

    return `<div style="display:flex;gap:0">
      <div style="display:flex;flex-direction:column;align-items:center;margin-right:10px;padding-top:3px">
        <div style="width:11px;height:11px;border-radius:50%;background:${sc};box-shadow:0 0 6px ${sc}99;flex-shrink:0"></div>
        ${!isLast?`<div style="width:1.5px;flex:1;min-height:14px;background:#3d3f5266;margin-top:3px"></div>`:''}
      </div>
      <div style="flex:1;padding-bottom:${isLast?'0':'13px'}">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:6px">
          <div style="font-size:11px;font-weight:600;color:var(--txt)">${h.icon} ${_esc(h.fromLabel)} <span style="color:var(--txt2);font-weight:400">→</span> ${_esc(h.toLabel)}</div>
          <div style="font-size:10.5px;color:var(--txt2);white-space:nowrap;padding-top:1px">${h.latMs} мс</div>
        </div>
        ${h.method?`<div style="font-size:10.5px;color:var(--blue);margin-top:1px">⚙ ${_esc(h.method)}</div>`:''}
        ${(h.pats||[]).map(p=>`<div style="font-size:10.5px;color:#bb9af7;margin-top:2px">🧩 ${_esc(p)}</div>`).join('')}
        ${qHtml}
        <div style="font-size:10px;color:${sc};margin-top:4px">${si} ${h.status==='fail'?'Ошибка':h.status==='slow'?'Медленно (деградация)':'OK'}</div>
      </div>
    </div>`;
  });

  const totalHops = req.path.length - 1;
  const pct = totalHops ? Math.round(trace.length / totalHops * 100) : 100;

  return `<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;padding-bottom:6px;border-bottom:1px solid #2a2b3d;font-size:10.5px">
    <span style="color:var(--txt2)">Шагов: <b style="color:var(--txt)">${trace.length}/${totalHops}</b></span>
    <span style="color:var(--txt2)">Накоплено: <b style="color:var(--yellow)">${req.accLat.toFixed(1)} мс</b></span>
    <span style="color:var(--txt2)">Прогресс: <b style="color:var(--blue)">${pct}%</b></span>
  </div>
  <div style="max-height:310px;overflow-y:auto;padding-right:3px">${rows.join('')}</div>`;
}


;
// ===== sim.js =====
// SIM — прогон симуляции, шарики-запросы, логи, клик по шарику
// (выделено из app.js при разбиении на модули)

// ═══════════════════════════════════════════════════════════════
// СИМУЛЯЦИЯ — шарики используют расчёт движка (реальная судьба)
// ═══════════════════════════════════════════════════════════════
let SIM={running:false,paused:false,rafId:null,dots:{},reqs:{},time:0,lastT:0,spawn:{}};
let _rId=0;

function runSim(){
  stopSim();
  if(typeof resetBrokerStates==='function')resetBrokerStates();
  analyze();
  const activeScs=(S.scenarios||[]).filter(function(sc){
    return sc.visible!==false&&sc.path&&sc.path.length>1;
  });
  if(!activeScs.length&&!S.blocks.some(function(b){return !new Set(S.conns.map(function(c){return c.to;})).has(b.id)&&S.conns.some(function(c){return c.from===b.id;});})){
    toast(t('sim_no_scenarios'));return;
  }
  SIM.running=true;SIM.paused=false;SIM.time=0;SIM.lastT=0;SIM.spawn={};SIM.dots={};SIM.reqs={};
  $('anim-layer').innerHTML='';
  if(typeof simPatReset==='function'){simPatReset();simPatLegend(true);}
  $('run-btn').style.display='none';$('pause-btn').style.display='';$('stop-btn').style.display='';
  SIM.rafId=requestAnimationFrame(simLoop);updateStatus();
}
function stopSim(){if(SIM.rafId)cancelAnimationFrame(SIM.rafId);Object.values(SIM.dots).forEach(d=>d?.remove());SIM.running=false;SIM.paused=false;SIM.dots={};SIM.reqs={};$('anim-layer').innerHTML='';if(typeof simPatReset==='function'){simPatReset();simPatLegend(false);}$('run-btn').style.display='';$('pause-btn').style.display='none';$('resume-btn').style.display='none';$('stop-btn').style.display='none';updateStatus();}
function pauseSim(){SIM.paused=true;$('pause-btn').style.display='none';$('resume-btn').style.display='';}
function resumeSim(){SIM.paused=false;$('pause-btn').style.display='';$('resume-btn').style.display='none';closeInsp();$('dot-modal').style.display='none';}

// сколько реальных запросов представляет 1 шарик (честность на ×10М)
function dotWeight(){return Math.max(1,Math.round(S.load/40));}

function simLoop(now){
  if(!SIM.running)return;
  if(!SIM.paused){
    const dt=SIM.lastT?Math.min(now-SIM.lastT,80):16;SIM.time+=dt;SIM.lastT=now;
    if(typeof simPatTick==='function')simPatTick(dt); // эффекты паттернов, backoff ретраев
    // Спавн по сценариям — каждый сценарий с шагами порождает шарики своего цвета
    const load=effLoad();
    const hasScs=(S.scenarios||[]).some(function(sc){return sc.visible!==false&&sc.path&&sc.path.length>1;});
    if(hasScs){
      (S.scenarios||[]).forEach(function(sc){
        if(sc.visible===false||!sc.path||sc.path.length<2)return;
        const rate=Math.min(12,Math.max(0.5,(sc.volume||100)/100*load));
        const interval=1000/rate;
        if(!SIM.spawn[sc.id])SIM.spawn[sc.id]=SIM.time;
        while(SIM.spawn[sc.id]<=SIM.time&&Object.keys(SIM.reqs).length<140){
          spawnScenario(sc);
          SIM.spawn[sc.id]+=interval;
        }
      });
    }else{
      // фолбэк: нет сценариев — спавним от source-блоков как раньше
      const hasInc=new Set(S.conns.map(c=>c.to));
      const sources=S.blocks.filter(b=>!hasInc.has(b.id)&&S.conns.some(c=>c.from===b.id));
      const rate=Math.min(12,Math.max(0.5,load/Math.max(1,sources.length)));
      const interval=1000/rate;
      if(!SIM.spawn['__src'])SIM.spawn['__src']=SIM.time;
      while(SIM.spawn['__src']<=SIM.time&&Object.keys(SIM.reqs).length<140){
        sources.forEach(s=>spawnReq(s.id));
        SIM.spawn['__src']+=interval;
      }
    }
    Object.values(SIM.reqs).forEach(req=>{
      if(req.status!=='flying'||!req.pts)return;
      const dot=SIM.dots[req.id];if(!dot)return;
      req.t+=req.speed;
      if(req.stopAt!=null&&req.t>=req.stopAt&&typeof simPatStop==='function'){simPatStop(req);return;} // паттерн оборвал хоп
      if(req.t>=1){if(req.rev&&typeof simPatRevDone==='function'){simPatRevDone(req);return;}onArrive(req);return;}
      const tt=req.rev?1-req.t:req.t; // rev — шарик идёт по ребру назад (retry, cache miss)
      const idx=Math.min(Math.floor(tt*(req.pts.length-1)),req.pts.length-2);
      const fr=tt*(req.pts.length-1)-idx;const p1=req.pts[idx],p2=req.pts[idx+1];
      const px=(p1.x+(p2.x-p1.x)*fr).toFixed(1); // pan/zoom даёт transform слоя anim-layer
      const py=(p1.y+(p2.y-p1.y)*fr).toFixed(1);
      if(req.isResponse){
        const angle=(Math.atan2(p2.y-p1.y,p2.x-p1.x)*180/Math.PI).toFixed(0);
        dot.setAttribute('transform',`translate(${px},${py}) rotate(${angle})`);
      } else {
        dot.setAttribute('cx',px);dot.setAttribute('cy',py);
      }
      dot.style.opacity='1';
    });
    // Тик консьюмеров: каждые 30 кадров (~500мс при 60fps)
    SIM._btick=(SIM._btick||0)+1;
    if(SIM._btick%30===0&&typeof tickBrokerConsumers==='function'){tickBrokerConsumers();if(typeof simPatKafka==='function')simPatKafka();}
  }
  SIM.rafId=requestAnimationFrame(simLoop);updateStatus();
}

// выбор пути: роутеры выбирают ОДНУ ветку, сервисы — тоже одну для анимации (фан-аут учтён в λ)
function nextHop(nodeId,visited){
  const outs=S.conns.filter(c=>c.from===nodeId&&!visited.has(c.to));
  if(!outs.length)return null;
  // Синхронные (не-брокерные) ветки приоритетнее для наглядности пути
  const sync=outs.filter(c=>{const t=gb(c.to);return t&&!['broker','queue'].includes(BASE[t.type]?.cat);});
  const pool=sync.length?sync:outs;
  return pool[Math.floor(Math.random()*pool.length)];
}
function buildPath(start){
  const path=[start],visited=new Set([start]);let cur=start,guard=0;
  while(guard++<20){const h=nextHop(cur,visited);if(!h)break;path.push(h.to);visited.add(h.to);cur=h.to;}
  return path;
}
// Спавн шарика строго по пути сценария (цвет = цвет сценария, путь = scenario.path)
function spawnScenario(sc){
  if(!sc||!sc.path||sc.path.length<2)return;
  const path=sc.path.slice();
  const color=sc.color||'#7aa2f7';
  const id='r'+(_rId++);
  const conn=S.conns.find(c=>c.from===path[0]&&c.to===path[1]);if(!conn)return;
  const pts=edgePts(conn);if(!pts)return;
  const req={id,path,idx:1,connId:conn.id,pts,t:0,speed:0,status:'flying',
             color,accLat:0,dead:false,trace:false,hopTrace:[],scenarioId:sc.id};
  setSpeed(req,path[1]);
  decideFate(req,path[1]);
  recordHop(req,path[0],path[1],conn);
  SIM.reqs[id]=req;
  const dot=document.createElementNS(NS,'circle');
  dot.setAttribute('r','6.5');dot.setAttribute('cx','-200');dot.setAttribute('cy','-200');
  dot.style.fill=req.color;dot.style.filter=`drop-shadow(0 0 5px ${req.color})`;dot.style.opacity='0';dot.style.cursor='pointer';
  dot.addEventListener('click',e=>{e.stopPropagation();showDotInfo(id);});
  dot.addEventListener('mousemove',e=>{showHoverTip(id,e.clientX,e.clientY);});
  dot.addEventListener('mouseleave',()=>{hideHoverTip();});
  $('anim-layer').appendChild(dot);SIM.dots[id]=dot;
}

// Выбрать сценарий для блока-источника (взвешенно по volume)
function pickScenario(startId){
  var m=(S.scenarios||[]).filter(function(sc){
    return sc.visible!==false&&sc.path&&sc.path.length>1&&sc.path[0]===startId;
  });
  if(!m.length)return null;
  var t=m.reduce(function(s,sc){return s+(sc.volume||1);},0),r=Math.random()*t,a=0;
  for(var i=0;i<m.length;i++){a+=(m[i].volume||1);if(r<=a)return m[i];}
  return m[m.length-1];
}

function spawnReq(start,opts){
  opts=opts||{};
  // Используем путь из сценария — так шарики идут через Kafka когда нужно
  const _sc=pickScenario(start);
  const path=_sc?_sc.path.slice():buildPath(start);
  if(path.length<2)return;
  const id='r'+(_rId++);
  const conn=S.conns.find(c=>c.from===path[0]&&c.to===path[1]);if(!conn)return;
  const pts=edgePts(conn);if(!pts)return;
  // судьба определяется на первом узле назначения по реальному dropRate
  const req={id,path,idx:1,connId:conn.id,pts,t:0,speed:0,status:'flying',color:'#7aa2f7',accLat:0,dead:false,trace:!!opts.trace,run:opts.run,hopTrace:[]};
  setSpeed(req,path[1]);
  decideFate(req,path[1]);
  if(req.trace)logHopFor(req,path[0],path[1],conn);
  recordHop(req,path[0],path[1],conn);
  SIM.reqs[id]=req;
  const dot=document.createElementNS(NS,'circle');dot.setAttribute('r',req.trace?'9':'6.5');dot.setAttribute('cx','-200');dot.setAttribute('cy','-200');
  dot.style.fill=req.color;dot.style.filter=`drop-shadow(0 0 ${req.trace?9:5}px ${req.trace?'#e0af68':req.color})`;dot.style.opacity='0';dot.style.cursor='pointer';
  if(req.trace)dot.setAttribute('stroke','#e0af68'),dot.setAttribute('stroke-width','2');
  dot.addEventListener('click',e=>{e.stopPropagation();showDotInfo(id);});
  dot.addEventListener('mousemove',e=>{showHoverTip(id,e.clientX,e.clientY);});
  dot.addEventListener('mouseleave',()=>{hideHoverTip();});
  $('anim-layer').appendChild(dot);SIM.dots[id]=dot;
}
function setSpeed(req,toId){const lat=Math.max(1,(gb(toId)?.rt?.effLat)||5);req.speed=Math.max(0.018,Math.min(0.6,24/Math.max(1,lat)*0.016*8*0.12*SPEED_MUL));}
function decideFate(req,toId){
  const rt=gb(toId)?.rt;if(!rt)return;
  req.accLat+=rt.effLat||0;
  if(!req.dead&&Math.random()<rt.dropRate){req.dead=true;req.color='#f7768e';req.deadAt=toId;}
  else if(rt.health==='warn'&&!req.dead){req.color='#e0af68';}
  const dot=SIM.dots[req.id];if(dot){dot.style.fill=req.color;dot.style.filter=`drop-shadow(0 0 5px ${req.color})`;}
  if(typeof simPatFate==='function')simPatFate(req,toId); // CB / retry / timeout / rate limit / cache / bulkhead
}
function onArrive(req){
  req.t=0;
  // C3: в раскрытом сервисе шарик сначала проходит цепочку контроллер → сервис → адаптер
  if(typeof zsSimArrive==='function'&&zsSimArrive(req))return;
  if(typeof simPatArrive==='function'&&simPatArrive(req))return; // паттерн/Kafka-парковка обработали прибытие
  if(req.dead&&!req.isResponse){const d=SIM.dots[req.id];if(d)setTimeout(()=>{d.remove();delete SIM.dots[req.id];delete SIM.reqs[req.id];},200);return;}
  if(req.idx>=req.path.length-1){
    if(req.isResponse){
      const d=SIM.dots[req.id];if(d)setTimeout(()=>{d.remove();delete SIM.dots[req.id];delete SIM.reqs[req.id];},200);return;
    }
    const lastId=req.path[req.path.length-1],ld=BASE[gb(lastId)?.type];
    if(!['db','cache','queue','broker','external','net'].includes(ld?.cat)){showDeadEnd(lastId);}
    else{
      flash(lastId,req.color);
      // Конец пути = брокер: событие опубликовано, но читать некому → копится lag
      if(['broker','queue'].includes(ld?.cat)&&typeof brokerProduce==='function')
        brokerProduce(lastId,{value:{req:req.id},reqId:req.id});
      if(req.trace)pushLog({run:req.run,hdr2:true,text:t('sim_arrived').replace('{lbl}',gb(lastId)?.customLabel||EL[gb(lastId)?.type]?.lbl)+(['db','cache'].includes(ld?.cat)?t('sim_forming_response'):'')});
      if(!req.dead&&['db','cache'].includes(ld?.cat))spawnResponse(req.path,req.color,req.trace?{run:req.run}:null);
    }
    const d=SIM.dots[req.id];if(d)setTimeout(()=>{d.remove();delete SIM.dots[req.id];delete SIM.reqs[req.id];},250);return;
  }
  req.idx++;const from=req.path[req.idx-1],to=req.path[req.idx];
  if(req.isResponse){
    const seg=getSegPts(from,to);if(!seg){delete SIM.reqs[req.id];SIM.dots[req.id]?.remove();delete SIM.dots[req.id];return;}
    req.pts=seg.pts;req.connId=seg.connId;req.t=0;req.status='flying';
    const _rc=S.conns.find(c=>(c.from===to&&c.to===from)||(c.from===from&&c.to===to));
    if(req.trace)logHopFor(req,from,to,_rc);
    recordHop(req,from,to,_rc);
    return;
  }
  const conn=S.conns.find(c=>c.from===from&&c.to===to);if(!conn){delete SIM.reqs[req.id];SIM.dots[req.id]?.remove();delete SIM.dots[req.id];return;}
  const pts=edgePts(conn);if(!pts){delete SIM.reqs[req.id];return;}

  // ── PRODUCE: два случая ──────────────────────────────────────
  const fromB=gb(from);
  const fromCat=BASE[fromB?.type]?.cat;
  if(typeof brokerProduce==='function'){
    // [1] broker-in-path: шарик прошёл через брокер — produce
    if(['broker','queue'].includes(fromCat)&&req.kDone!==from){ // Kafka: уже записано при парковке
      brokerProduce(from,{value:{req:req.id},reqId:req.id});
    }
    // [2] implicit: сервис/gw/auth → боковая связь на брокер (Kafka не в sc.path)
    if(!req.dead&&(fromCat==='svc'||fromCat==='gw'||fromCat==='auth')){
      S.conns.filter(c=>c.from===from).forEach(c=>{
        const bt=gb(c.to);
        if(bt&&['broker','queue'].includes(BASE[bt.type]?.cat)&&!req.path.includes(c.to)){
          brokerProduce(c.to,{value:{req:req.id,src:from},reqId:req.id}); // без ключа — key_strategy брокера
        }
      });
    }
  }
  // consume — НЕ здесь; tickBrokerConsumers() вызывается из simLoop каждые 30 кадров

  req.connId=conn.id;req.pts=pts;setSpeed(req,to);decideFate(req,to);req.status='flying';
  if(req.trace)logHopFor(req,from,to,conn);
  recordHop(req,from,to,conn);
}
function spawnResponse(path,color,opts){
  opts=opts||{};
  if(path.length<2)return;
  const revPath=[...path].reverse();
  const id='r'+(_rId++);
  const seg=getSegPts(revPath[0],revPath[1]);if(!seg)return;
  const req={id,path:revPath,idx:1,pts:seg.pts,connId:seg.connId,t:0,speed:0.04,status:'flying',color,isResponse:true,accLat:0,trace:!!opts.trace||!!opts.run,run:opts.run,hopTrace:[]};
  const _respConn=S.conns.find(c=>(c.from===revPath[1]&&c.to===revPath[0])||(c.from===revPath[0]&&c.to===revPath[1]));
  if(req.trace)logHopFor(req,revPath[0],revPath[1],_respConn);
  recordHop(req,revPath[0],revPath[1],_respConn);
  SIM.reqs[id]=req;
  const tri=document.createElementNS(NS,'polygon');
  tri.setAttribute('points',req.trace?'0,-7 12,0 0,7':'0,-5 9,0 0,5');
  tri.style.fill=color;tri.style.filter=`drop-shadow(0 0 ${req.trace?8:4}px ${req.trace?'#e0af68':color})`;tri.style.opacity='0';tri.style.cursor='pointer';
  tri.addEventListener('click',e=>{e.stopPropagation();showDotInfo(id);});
  tri.addEventListener('mousemove',e=>{showHoverTip(id,e.clientX,e.clientY);});
  tri.addEventListener('mouseleave',()=>{hideHoverTip();});
  $('anim-layer').appendChild(tri);SIM.dots[id]=tri;
}
function flash(nid,color){const b=gb(nid);if(!b)return;const fl=document.createElementNS(NS,'circle');fl.setAttribute('cx',b.x+bw(b)/2);fl.setAttribute('cy',b.y+bh(b)/2);fl.setAttribute('r','8');fl.style.fill=color;fl.style.opacity='0.55';$('anim-layer').appendChild(fl);let r=8;const iv=setInterval(()=>{r+=3;fl.setAttribute('r',r);fl.style.opacity=Math.max(0,0.55-(r-8)/30);if(r>34){clearInterval(iv);fl.remove();}},22);}
let _deShown={};
function showDeadEnd(nodeId){const b=gb(nodeId);if(!b)return;if(_deShown[nodeId]&&Date.now()-_deShown[nodeId]<4000)return;_deShown[nodeId]=Date.now();const r=svgRct();const z=S.zoom||1;const el=document.createElement('div');el.style.cssText=`position:fixed;left:${(b.x+bw(b)/2)*z+S.panX+r.left}px;top:${(b.y-14)*z+S.panY+r.top}px;transform:translateX(-50%);background:#1a1b26;border:1.5px solid #e0af68;border-radius:8px;padding:7px 11px;font-size:11px;color:#e0af68;z-index:200;white-space:nowrap;pointer-events:none`;el.textContent=t('sim_dead_end').replace('{lbl}',EL[b.type].lbl);document.body.appendChild(el);setTimeout(()=>el.remove(),3500);}

// ═══════════════════════════════════════════════════════════════
// 📋 ТРАССИРОВКА — лог пути запроса: бизнес-смысл + технический вызов
// ═══════════════════════════════════════════════════════════════
let LOG=[],TRACE_RUN=0;
const HOP_BIZ_KEYS={
  'actor>client':'hb_actor_client','actor>gw':'hb_actor_gw','actor>net':'hb_actor_net',
  'actor>svc':'hb_actor_svc','actor>bff':'hb_actor_bff',
  'client>gw':'hb_client_gw','client>net':'hb_client_net','client>svc':'hb_client_svc','client>bff':'hb_client_bff',
  'bff>gw':'hb_bff_gw','bff>net':'hb_bff_net','bff>db':'hb_bff_db','bff>cache':'hb_bff_cache',
  'gw>bff':'hb_gw_bff','net>bff':'hb_net_bff','net>net':'hb_net_net',
  'gw>cache':'hb_gw_cache','gw>svc':'hb_gw_svc','gw>net':'hb_gw_net','net>svc':'hb_net_svc',
  'svc>db':'hb_svc_db','svc>cache':'hb_svc_cache','svc>broker':'hb_svc_broker','svc>queue':'hb_svc_queue',
  'svc>svc':'hb_svc_svc','svc>external':'hb_svc_external','bff>svc':'hb_bff_svc',
  'broker>svc':'hb_broker_svc','queue>svc':'hb_queue_svc',
};
function hopBiz(fc,tc){const k=HOP_BIZ_KEYS[fc+'>'+tc];if(k)return t(k);return tc==='db'?t('hb_fallback_db'):tc==='cache'?t('hb_fallback_cache'):tc==='broker'?t('hb_fallback_broker'):t('hb_fallback_default');}
function hopTech(from,to,conn,isResp){
  if(conn){
    if(isResp){const r=connResp(conn)||conn.respLabel;if(r)return r;}
    else{const a=conn.label||connApi(conn)||conn.reqLabel;if(a)return a;}
  }
  const tc=BASE[to.type]?.cat,fc=BASE[from.type]?.cat;
  if(isResp)return BASE[to.type]?.cat==='actor'?t('tech_result_user'):t('tech_return_data');
  if(tc==='db')return t('tech_sql');
  if(tc==='cache')return t('tech_cache_get');
  if(tc==='broker')return t('tech_produce');
  if(tc==='queue')return t('tech_enqueue');
  if(tc==='gw')return t('tech_https');
  if(tc==='external')return t('tech_external');
  if(fc==='gw'&&tc==='svc')return t('tech_gw_proxy');
  if(tc==='svc')return t('tech_internal_api');
  if(tc==='net')return t('tech_net_route');
  return t('tech_http_generic');
}
function logHopFor(req,fromId,toId,conn){
  const from=gb(fromId),to=gb(toId);if(!from||!to)return;
  const fc=BASE[from.type]?.cat,tc=BASE[to.type]?.cat;
  const status=(req.dead&&req.deadAt===toId)?'fail':(to.rt?.health==='error'?'fail':to.rt?.health==='warn'?'slow':'ok');
  pushLog({run:req.run,reqId:req.id,resp:!!req.isResponse,
    from:from.customLabel||EL[from.type]?.lbl, to:to.customLabel||EL[to.type]?.lbl,
    biz:req.isResponse?t('log_biz_resp_return'):hopBiz(fc,tc),
    tech:hopTech(from,to,conn,req.isResponse), status});
}
// ОБХОД ДЕРЕВА ВЫЗОВОВ — детерминированный (вызов → вглубь → возврат)
// Это основа и для логов, и для UML: настоящая семантика sequence-диаграммы.
function walkCalls(startId,maxDepth){
  maxDepth=maxDepth||14;
  const events=[],usedConn=new Set(),deferred=[];
  function visit(id,depth){
    if(depth>maxDepth)return;
    const outs=S.conns.filter(c=>c.from===id&&!usedConn.has(c.id))
      .sort((a,b)=>{const ta=gb(a.to),tb=gb(b.to);return (ta?.y||0)-(tb?.y||0)||(ta?.x||0)-(tb?.x||0);});
    for(const c of outs){
      usedConn.add(c.id);
      const to=gb(c.to);if(!to)continue;
      const tcat=BASE[to.type]?.cat;
      const async=(tcat==='broker'||tcat==='queue');
      events.push({kind:async?'async':'call',from:id,to:c.to,conn:c,depth});
      if(async){
        // async = «отправил и забыл»: продюсер НЕ ждёт. Ветку брокера обрабатываем ОТДЕЛЬНО, потом —
        // чтобы столбик продюсера закрылся сразу, а не тянулся через всю цепочку уведомлений.
        deferred.push({id:c.to,depth});
      }else{
        visit(c.to,depth+1);
        events.push({kind:'return',from:c.to,to:id,conn:c,depth}); // синхронный вызов всегда возвращает
      }
    }
  }
  visit(startId,0);
  // асинхронные ветки (брокер → консьюмеры) — после синхронного потока, как отдельная фаза
  let guard=0;
  while(deferred.length&&guard++<40){const d=deferred.shift();if(!usedConn.has('async-root-'+d.id)){usedConn.add('async-root-'+d.id);events.push({kind:'asyncphase',from:d.id,to:d.id,depth:d.depth});visit(d.id,d.depth+1);}}
  return events;
}
function logFromEvents(events,runId){
  const out=[];
  events.forEach(ev=>{
    if(ev.kind==='asyncphase')return; // маркер фазы — в логе не нужен
    const from=gb(ev.from),to=gb(ev.to);if(!from||!to)return;
    const fc=BASE[from.type]?.cat,tc=BASE[to.type]?.cat;
    let biz,tech,status,arrow;
    if(ev.kind==='return'){
      const toActor=BASE[to.type]?.cat==='actor';
      biz=toActor?t('log_biz_user_sees'):t('log_biz_return_caller');
      tech=connResp(ev.conn)||ev.conn.respLabel||t('tech_return_data');
      status=from.rt?.health==='error'?'fail':from.rt?.health==='warn'?'slow':'ok';arrow='◀';
    }else if(ev.kind==='async'){
      biz=hopBiz(fc,tc);tech=ev.conn.label||ev.conn.reqLabel||t('tech_publish_async');status='ok';arrow='⇢';
    }else{
      biz=hopBiz(fc,tc);tech=hopTech(from,to,ev.conn,false);
      status=to.rt?.health==='error'?'fail':to.rt?.health==='warn'?'slow':'ok';arrow='→';
    }
    out.push({run:runId,depth:ev.depth,kind:ev.kind,arrow,
      from:from.customLabel||EL[from.type]?.lbl,to:to.customLabel||EL[to.type]?.lbl,biz,tech,status});
  });
  return out;
}
function pushLog(e){e.t=Date.now();LOG.push(e);if(LOG.length>500)LOG.shift();if(sideTab==='logs')renderLogs();}
function clearLog(){LOG=[];if(TRACE_TIMER){clearInterval(TRACE_TIMER);TRACE_TIMER=null;}renderLogs();}
let TRACE_TIMER=null;
function statusForName(name){
  const b=S.blocks.find(x=>(x.customLabel||EL[x.type]?.lbl)===name);
  if(!b||!b.rt)return 'ok';
  return b.rt.health==='error'?'fail':b.rt.health==='warn'?'slow':'ok';
}
// лог из АВТОРСКОГО сценария актора (приоритет) — то, что ты написал
function logFromScenario(text,runId){
  if(typeof parseSeq!=='function')return null;
  const model=parseSeq(text);if(!model.events.length)return null;
  const out=[];let depth=0;
  model.events.forEach(ev=>{
    if(ev.type==='frag'){out.push({run:runId,frag:true,depth,text:ev.kind.toUpperCase()+(ev.label?': '+ev.label:'')});depth++;return;}
    if(ev.type==='else'){out.push({run:runId,frag:true,depth:Math.max(0,depth-1),text:t('log_else')+(ev.label?': '+ev.label:'')});return;}
    if(ev.type==='end'){depth=Math.max(0,depth-1);return;}
    if(ev.type==='note')return;
    if(ev.type==='msg'){
      const from=model.lanes[ev.from]?.name||'?',to=model.lanes[ev.to]?.name||'?';
      out.push({run:runId,depth,kind:ev.dashed?'return':(ev.async?'async':'call'),
        arrow:ev.dashed?'◀':ev.async?'⇢':'→',from,to,
        biz:ev.note||(ev.dashed?t('log_return_result'):t('log_scenario_step')),
        tech:ev.text||'—',status:ev.dashed?statusForName(from):statusForName(to)});
    }
  });
  return out;
}
// Строит лог трассировки из структурированного сценария S.scenarios[i]
function logFromScenarioObj(sc, runId){
  if(!sc||!sc.path||!sc.steps)return null;
  var out=[];
  for(var i=0;i<sc.path.length-1;i++){
    var fromId=sc.path[i],toId=sc.path[i+1];
    var from=gb(fromId),to=gb(toId);
    if(!from||!to)continue;
    var step=sc.steps[i]||{};
    var isReturn=(!step.name&&!step.verb&&!step.uri&&!!step.resp);
    var biz=step.name||(step.resp?'← '+step.resp:'—');
    var tech=step.verb&&step.uri?step.verb+' '+step.uri:step.verb||step.uri||(step.resp||'—');
    var health=(gb(toId)?.rt?.health)||'ok';
    out.push({
      run:runId, kind:isReturn?'return':'call', arrow:isReturn?'◀':'→',
      from:from.customLabel||EL[from.type]?.lbl||fromId,
      to:to.customLabel||EL[to.type]?.lbl||toId,
      depth:0, biz:biz, tech:tech,
      status:health==='error'?'fail':health==='warn'?'slow':'ok'
    });
  }
  return out.length?out:null;
}

function traceRequest(scId){
  analyze();
  // Ищем сценарий по id (новый режим) или по блоку-источнику (fallback)
  var sc=(S.scenarios||[]).find(function(s){return s.id===scId;});
  var entries=sc?logFromScenarioObj(sc,0):null;
  var fromScenario=!!entries;
  if(!entries){
    // fallback: авто-обход от первого источника
    var hasInc=new Set(S.conns.map(function(c){return c.to;}));
    var src=S.blocks.find(function(b){return !hasInc.has(b.id)&&S.conns.some(function(c){return c.from===b.id;});});
    if(!src){toast(t('sim_no_src'));return;}
    var ev=walkCalls(src.id);
    if(!ev.length){toast(t('sim_no_src_conns'));return;}
    entries=logFromEvents(ev,0);
  }
  const runId=++TRACE_RUN;entries.forEach(function(e){e.run=runId;});
  const calls=entries.filter(function(e){return !e.frag&&e.kind!=='return';}).length;
  const label=sc?sc.name:t('sim_auto_from_scheme');
  LOG.push({hdr:true,run:runId,text:'▶ '+label+' · '+calls+' '+t('sim_steps')+(fromScenario?'':t('sim_auto_suffix'))});
  if(TRACE_TIMER)clearInterval(TRACE_TIMER);
  switchTab('logs');renderLogs();
  let i=0;
  TRACE_TIMER=setInterval(()=>{
    if(i>=entries.length){clearInterval(TRACE_TIMER);TRACE_TIMER=null;LOG.push({hdr2:true,run:runId,text:typeof t==='function'?t('log_done'):'✓ Done'});renderLogs();return;}
    pushLog(entries[i++]);
  },230);
}
function renderLogs(){
  const c=$('side-logs');if(!c)return;
  // Сценарии вместо блоков-источников — трассировка идёт по scenario.steps
  const scOpts=(S.scenarios||[]).filter(function(sc){return sc.visible!==false&&sc.path&&sc.path.length>1;})
    .map(function(sc){return `<option value="${esc(sc.id)}">${esc(sc.name||sc.id)}</option>`;}).join('')
    ||(typeof t==='function'?`<option value="">${t('log_no_scenarios')}</option>`:'<option value=""></option>');
  let h=`<div style="margin-bottom:8px">
    <select id="trace-src" style="width:100%;background:var(--bg3);color:var(--txt);border:1px solid var(--brd2);border-radius:6px;padding:5px 7px;font-size:11px;margin-bottom:6px">${scOpts}</select>
    <div style="display:flex;gap:6px">
      <button onclick="traceRequest(document.getElementById('trace-src').value)" style="flex:1;padding:8px;border:1px solid #e0af68;border-radius:6px;background:#e0af6822;color:#e0af68;cursor:pointer;font-size:11.5px;font-weight:600">${typeof t==='function'?t('log_trace_btn'):'▶ Trace'}</button>
      <button onclick="clearLog()" style="padding:8px 10px;border:1px solid #4a4c6a;border-radius:6px;background:transparent;color:#787c99;cursor:pointer;font-size:11.5px">${typeof t==='function'?t('log_clear_btn'):'Clear'}</button>
    </div>
  </div>`;
  if(!LOG.length){h+=`<div style="color:var(--txt2);font-size:11px;line-height:1.7">${typeof t==='function'?t('log_empty_hint'):''}</div>`;c.innerHTML=h;return;}
  LOG.forEach(e=>{
    if(e.hdr){h+=`<div style="margin:10px 0 4px;font-size:11px;font-weight:700;color:var(--yellow);border-bottom:1px solid var(--brd);padding-bottom:3px">${esc(e.text)}</div>`;return;}
    if(e.hdr2){h+=`<div style="font-size:10.5px;color:var(--green);font-weight:600;margin:3px 0 8px;padding-left:2px">${esc(e.text)}</div>`;return;}
    if(e.frag){h+=`<div style="margin-left:${(e.depth||0)*11}px;font-size:10px;color:var(--purple);font-weight:600;margin-top:3px;margin-bottom:2px">⎇ ${esc(e.text)}</div>`;return;}
    const clr=e.status==='fail'?'#f7768e':e.status==='slow'?'#e0af68':'#9ece6a';
    const st=e.status==='fail'?t('status_error'):e.status==='slow'?t('status_slow'):t('status_ok');
    const ind=(e.depth||0)*11;
    const dashed=e.kind==='return'?'border-left-style:dashed;':'';
    h+=`<div style="margin-left:${ind}px;background:var(--bg1);border-left:2px solid ${clr};${dashed}border-radius:5px;padding:5px 7px;margin-bottom:4px;font-size:10.5px;line-height:1.45">
      <div style="color:var(--txt);font-weight:600">${e.arrow} ${esc(e.from)} → ${esc(e.to)} <span style="float:right;color:${clr};font-size:9px">${st}</span></div>
      <div style="color:var(--txt2)">🧩 ${esc(e.biz)}</div>
      <div style="color:var(--blue)">⚙ ${esc(e.tech)}</div>
    </div>`;
  });
  c.innerHTML=h;c.scrollTop=c.scrollHeight;
}

// showBrokerInspector → заменён на openBrokerInspector в broker-inspector.js
