  if(!ov){ov=document.createElement('div');ov.id='dbpick-modal';ov.className='modal-ov';ov.onclick=e=>{if(e.target===ov)ov.style.display='none';};document.body.appendChild(ov);}
  ov.innerHTML=inner;ov.style.display='flex';
